/* GEOS3141 review deck, used by review.html (and index.html for the due count).
   CARDS is a plain global array so the page works from file:// with no fetch.
   Each card: {id, lecture, kind, front, back} plus, for checkpoints, opts (the
   choices) and ans (the right one), and for self-test questions, lvl.
   kind: term (glossary), mc (checkpoint), q (self-test or short answer).
   Ids are what the schedule in localStorage (geos3141-srs) is keyed on, so
   don't renumber them. The block above the marker is generated from each
   lecture page by tools/build_cards.py; add extra cards below the marker. */
var CARDS = [
 /* Lecture 1: 36 terms, 11 checkpoints, 10 self-test */
 {"id": "L1-g-assay", "lecture": 1, "kind": "term", "front": "Assay", "back": "A laboratory chemical analysis that measures how much of a metal is in a sample."},
 {"id": "L1-g-bonanza", "lecture": 1, "kind": "term", "front": "Bonanza", "back": "Exceptionally high grade, usually over 100 g/t gold, typical of some epithermal and orogenic deposits."},
 {"id": "L1-g-brownfield", "lecture": 1, "kind": "term", "front": "Brownfield", "back": "Exploration in or near an existing or historic mining area."},
 {"id": "L1-g-concentration-factor", "lecture": 1, "kind": "term", "front": "Concentration factor", "back": "Economic grade divided by average crustal abundance: how much a process has to enrich an element to make ore."},
 {"id": "L1-g-connate-water", "lecture": 1, "kind": "term", "front": "Connate water", "back": "Water trapped in sediment pores when the sediment was deposited."},
 {"id": "L1-g-critical-minerals", "lecture": 1, "kind": "term", "front": "Critical minerals", "back": "A policy term for commodities a particular country considers essential and supply-risky. Lists differ between countries and departments."},
 {"id": "L1-g-cut-off-grade", "lecture": 1, "kind": "term", "front": "Cut-off grade", "back": "The lowest grade that can be mined and processed at a profit. Rock below it is treated as waste."},
 {"id": "L1-g-diatreme", "lecture": 1, "kind": "term", "front": "Diatreme", "back": "A volcanic pipe filled with broken rock, blasted out when magma or gas meets groundwater explosively."},
 {"id": "L1-g-epigenetic", "lecture": 1, "kind": "term", "front": "Epigenetic", "back": "Ore introduced after its host rock formed, such as any vein."},
 {"id": "L1-g-exsolution", "lecture": 1, "kind": "term", "front": "Exsolution", "back": "One phase separating out of another as conditions change, like water bubbling out of a rising magma as pressure drops."},
 {"id": "L1-g-gangue", "lecture": 1, "kind": "term", "front": "Gangue", "back": "Minerals mined along with the ore that have no value in that deposit, such as quartz, carbonates and usually pyrite. Pronounced 'gang'."},
 {"id": "L1-g-grade", "lecture": 1, "kind": "term", "front": "Grade", "back": "The concentration of the valuable commodity in ore: g/t for precious metals, wt% for base metals. Waste has no grade."},
 {"id": "L1-g-grade-control", "lecture": 1, "kind": "term", "front": "Grade control", "back": "Day-to-day sampling and assaying at an operating mine to decide which blasted rock goes to the mill and which to the waste dump."},
 {"id": "L1-g-greenfield", "lecture": 1, "kind": "term", "front": "Greenfield", "back": "Exploration in an area with no known deposits or previous mining."},
 {"id": "L1-g-hydrothermal-alteration", "lecture": 1, "kind": "term", "front": "Hydrothermal alteration", "back": "Changes to a rock's minerals, texture and chemistry caused by reaction with hot fluids."},
 {"id": "L1-g-hypogene", "lecture": 1, "kind": "term", "front": "Hypogene", "back": "Formed by rising fluids from depth, usually hot hydrothermal fluids."},
 {"id": "L1-g-iocg", "lecture": 1, "kind": "term", "front": "IOCG", "back": "Iron oxide copper-gold deposit, the class defined by Olympic Dam."},
 {"id": "L1-g-joint-venture", "lecture": 1, "kind": "term", "front": "Joint venture", "back": "A partnership where companies share the cost and ownership of a project, common when a junior brings in a major to fund a mine."},
 {"id": "L1-g-jorc-code", "lecture": 1, "kind": "term", "front": "JORC Code", "back": "The Australasian code for reporting exploration results, mineral resources and ore reserves, signed off by a Competent Person."},
 {"id": "L1-g-kimberlite", "lecture": 1, "kind": "term", "front": "Kimberlite", "back": "A volatile-rich ultramafic rock erupted from deep in the mantle in narrow pipes; the classic diamond host."},
 {"id": "L1-g-lamproite", "lecture": 1, "kind": "term", "front": "Lamproite", "back": "An ultrapotassic, mantle-derived alkaline volcanic rock. Like kimberlite it can carry diamonds, as at Argyle."},
 {"id": "L1-g-ligand", "lecture": 1, "kind": "term", "front": "Ligand", "back": "An ion or molecule (such as Cl⁻ or HS⁻) that bonds to a metal in solution and lets the fluid carry it."},
 {"id": "L1-g-metallotect", "lecture": 1, "kind": "term", "front": "Metallotect", "back": "Any geological, tectonic, lithological or geochemical feature that helped concentrate one or more elements."},
 {"id": "L1-g-metasomatism", "lecture": 1, "kind": "term", "front": "Metasomatism", "back": "Changing a rock's chemical composition by adding or removing components through fluid flow, in an open system."},
 {"id": "L1-g-meteoric-water", "lecture": 1, "kind": "term", "front": "Meteoric water", "back": "Water that fell as rain or snow and entered the ground as groundwater."},
 {"id": "L1-g-mineral-resource", "lecture": 1, "kind": "term", "front": "Mineral resource", "back": "An estimate of tonnage and grade in the ground with reasonable prospects of eventual economic extraction: inferred, indicated or measured."},
 {"id": "L1-g-modifying-factors", "lecture": 1, "kind": "term", "front": "Modifying factors", "back": "Mining, metallurgical, economic, marketing, legal, environmental, social and government considerations used to turn resources into reserves."},
 {"id": "L1-g-ore-mineral", "lecture": 1, "kind": "term", "front": "Ore mineral", "back": "A mineral you get paid for. Which minerals count depends on the deposit and the market."},
 {"id": "L1-g-ore-reserve", "lecture": 1, "kind": "term", "front": "Ore reserve", "back": "The part of a measured or indicated resource shown to be economically mineable after the modifying factors: probable or proved."},
 {"id": "L1-g-porphyry", "lecture": 1, "kind": "term", "front": "Porphyry", "back": "A large, low-grade copper (gold, molybdenum) deposit formed by fluids from an oxidised intrusion in an arc."},
 {"id": "L1-g-ppm-and-ppb", "lecture": 1, "kind": "term", "front": "Ppm and ppb", "back": "Parts per million and per billion by mass. 1 ppm = 1 g/t = 1000 ppb; 1% = 10 000 ppm."},
 {"id": "L1-g-regolith", "lecture": 1, "kind": "term", "front": "Regolith", "back": "The blanket of weathered rock, soil and transported sediment over fresh bedrock; tens to over 100 m thick in much of Australia."},
 {"id": "L1-g-supergene", "lecture": 1, "kind": "term", "front": "Supergene", "back": "Formed by descending surface waters during weathering, which leach metals near the surface and redeposit them lower down."},
 {"id": "L1-g-syngenetic", "lecture": 1, "kind": "term", "front": "Syngenetic", "back": "Ore formed at the same time as its host rock, such as a seafloor massive sulphide layer or a placer."},
 {"id": "L1-g-tonnage", "lecture": 1, "kind": "term", "front": "Tonnage", "back": "The mass of ore in a deposit, usually in millions of tonnes (Mt)."},
 {"id": "L1-g-top-cut", "lecture": 1, "kind": "term", "front": "Top cut", "back": "Capping very high assays at a set value during resource estimation so a few extreme results don't inflate the overall grade."},
 {"id": "L1-cp1", "lecture": 1, "kind": "mc", "front": "The copper price halves overnight. What happens to the copper ore at a mine?", "opts": ["Nothing. The rocks haven’t changed.", "Some of it becomes waste because the cut-off grade rises.", "The grade of every block drops."], "ans": "Some of it becomes waste because the cut-off grade rises.", "back": "Ore is defined by profit. A lower price means a higher cut-off, so lower-grade blocks become waste. The grades themselves don’t change."},
 {"id": "L1-cp2", "lecture": 1, "kind": "mc", "front": "1 g/t is the same as...", "opts": ["1 ppm", "1 ppb", "0.1%"], "ans": "1 ppm", "back": "A tonne is a million grams, so 1 g in a tonne is one part per million. 0.1% would be 1000 ppm."},
 {"id": "L1-cp3", "lecture": 1, "kind": "mc", "front": "A deposit is 20 Mt at 2.5 g/t Au. Roughly how much gold does it contain?", "opts": ["About 50 000 oz", "About 1.6 million oz", "About 50 million oz"], "ans": "About 1.6 million oz", "back": "20 000 000 t × 2.5 g/t = 50 000 000 g. Divide by 31.1 g/oz and you get about 1.6 million ounces."},
 {"id": "L1-cp4", "lecture": 1, "kind": "mc", "front": "Which of these can be converted straight into an ore reserve?", "opts": ["An inferred resource", "An indicated resource", "Exploration results"], "ans": "An indicated resource", "back": "Indicated converts to probable, and measured to proved or probable. Inferred never converts directly."},
 {"id": "L1-cp5", "lecture": 1, "kind": "mc", "front": "A galena-sphalerite vein with chalcedony bands and no chalcopyrite cuts across bedding. Best label?", "opts": ["Syngenetic and hypothermal", "Epigenetic and epithermal", "Syngenetic and epithermal"], "ans": "Epigenetic and epithermal", "back": "Cutting across bedding makes it epigenetic. Low-temperature minerals and no chalcopyrite point to the shallow, cool epithermal zone."},
 {"id": "L1-cp6", "lecture": 1, "kind": "mc", "front": "Your company wants a SEDEX zinc deposit. Where do you look first?", "opts": ["A continental arc above a subduction zone", "A rifted continental margin or rift basin", "The middle of a stable craton with no basins"], "ans": "A rifted continental margin or rift basin", "back": "SEDEX forms where basin brines rise up growth faults in rifted margins and intracontinental rifts, not in arcs."},
 {"id": "L1-cp7", "lecture": 1, "kind": "mc", "front": "In one sentence, what is an ore deposit?", "opts": ["Any rock that contains metal", "An unusually high concentration of elements that are normally spread thinly through the crust", "Any rock that formed from magma"], "ans": "An unusually high concentration of elements that are normally spread thinly through the crust", "back": "Everything else in this lecture hangs off that: when it counts as ore, how much concentrating it takes, and what processes do it."},
 {"id": "L1-cp8", "lecture": 1, "kind": "mc", "front": "An alkaline syenite with carbonatite dykes is most likely to host...", "opts": ["chromite and platinum group elements", "porphyry copper-gold", "rare earths and phosphate"], "ans": "rare earths and phosphate", "back": "Small-degree mantle melts concentrate incompatible elements. Tholeiites give Cr-Ni-PGE; wet, oxidised calc-alkaline magmas give porphyries."},
 {"id": "L1-cp9", "lecture": 1, "kind": "mc", "front": "Hydrothermal fluid flows through a permeable fault zone for a long time, but nothing there cools it, boils it, mixes with it or reacts with it. Which link is missing?", "opts": ["A metal source", "A trap: something that makes the fluid drop its metal", "A pathway"], "ans": "A trap: something that makes the fluid drop its metal", "back": "Fluids are usually undersaturated, so they only drop metal when cooling, boiling, mixing or reaction with rock changes them fast."},
 {"id": "L1-cp10", "lecture": 1, "kind": "mc", "front": "Why was the Argyle diamond deposit not followed up properly at first?", "opts": ["It was too deep to drill", "The working model said economic diamonds only occur in kimberlite, and Argyle is hosted by lamproite", "Its diamonds were too small to see"], "ans": "The working model said economic diamonds only occur in kimberlite, and Argyle is hosted by lamproite", "back": "Use a model as a tool for finding the next deposit, not as a definition."},
 {"id": "L1-cp11", "lecture": 1, "kind": "mc", "front": "The ore suites are worth 50 per cent. What do they lean on most directly?", "opts": ["Describing ore and gangue minerals, textures and likely setting, using this lecture’s vocabulary", "Spreadsheet economics", "Seminar slides"], "ans": "Describing ore and gangue minerals, textures and likely setting, using this lecture’s vocabulary", "back": "Your first ore suite page isn’t marked but gets feedback, so take it seriously and redo it."},
 {"id": "L1-st1", "lecture": 1, "kind": "q", "lvl": "Recall", "front": "A copper deposit hasn’t changed since last year, but the company has stopped calling part of it ore. How is that possible?", "back": "Ore is defined by whether it can be extracted at a profit. If the copper price fell or costs rose, the cut-off grade went up and the lower-grade parts are no longer economic, so they’re reclassified. The rocks are the same; the economics changed."},
 {"id": "L1-st2", "lecture": 1, "kind": "q", "lvl": "Recall", "front": "Why is pyrite gangue at most deposits but ore at Mount Isa?", "back": "Pyrite is only ore if someone pays for it. Phosphate Hill, south of Mount Isa, needs sulphuric acid to process phosphate, and pyrite (FeS₂) is a sulphur source for that acid. Elsewhere it’s worthless and a liability, because it makes acid mine drainage."},
 {"id": "L1-st3", "lecture": 1, "kind": "q", "lvl": "Calculate", "front": "Calculate the concentration factor for copper if average crust is 55 ppm and the economic grade is 1%.", "back": "1% is 10 000 ppm. 10 000 ÷ 55 ≈ 180, so copper must be concentrated about 180 times."},
 {"id": "L1-st4", "lecture": 1, "kind": "q", "lvl": "Think", "front": "Zinc needs a bigger concentration factor than nickel, yet zinc deposits are more common. Does that contradict the idea?", "back": "No. The factor is how much enrichment is needed, not how often it happens. Zinc moves easily in low-temperature saline basin fluids, which circulate commonly. Nickel sulphide ore needs a sulphide liquid to separate from a hot ultramafic magma, which is much rarer."},
 {"id": "L1-st5", "lecture": 1, "kind": "q", "lvl": "Recall", "front": "Why do companies sample every metre of half core, even sections with no visible mineralisation?", "back": "Grade is an average over the whole interval. Sampling only what looks mineralised would bias the average upwards. And in many gold deposits the gold is invisible anyway."},
 {"id": "L1-st6", "lecture": 1, "kind": "q", "lvl": "Think", "front": "A company reports a large inferred resource and says it’s \"about to start mining\". What should make you sceptical?", "back": "Inferred is the lowest confidence category and can’t become a reserve directly. Mining needs indicated or measured resources plus studies showing the modifying factors are satisfied, which usually takes years."},
 {"id": "L1-st7", "lecture": 1, "kind": "q", "lvl": "Apply", "front": "A quartz vein full of chalcopyrite cuts bedding in a sandstone. Syngenetic or epigenetic, and is it likely epithermal?", "back": "Epigenetic, because it cuts bedding. Probably not epithermal: abundant chalcopyrite suggests more than about 200 °C, pointing to mesothermal or deeper conditions, or a porphyry-related setting."},
 {"id": "L1-st8", "lecture": 1, "kind": "q", "lvl": "Apply", "front": "You’re exploring for primary REE in a region with a tholeiitic gabbro, a calc-alkaline granodiorite and an alkaline syenite with carbonatite dykes. Where do you start?", "back": "The alkaline syenite and carbonatite. REE are incompatible elements concentrated by small-degree mantle melting, which is exactly what produces alkaline magmas and carbonatites."},
 {"id": "L1-st9", "lecture": 1, "kind": "q", "lvl": "Think", "front": "Why is an alteration halo usually a better exploration target than the ore body?", "back": "The fluid reacted with a much larger volume of rock than the ore occupies, so the halo can be orders of magnitude bigger and easier to detect. Zoning within it then helps you vector toward the ore."},
 {"id": "L1-st10", "lecture": 1, "kind": "q", "lvl": "Synthesise", "front": "Give two different reasons why a region with lots of hot fluid flow might have no deposit.", "back": "Any broken link works. No trap, so the metals stayed dissolved and dispersed. No focusing structure, so metal spread thinly through a huge volume. Or a deposit formed and was later eroded, so preservation failed."},
 /* Lecture 2: 40 terms, 12 checkpoints, 10 self-test */
 {"id": "L2-g-acid-mine-drainage", "lecture": 2, "kind": "term", "front": "Acid mine drainage", "back": "Acidic, metal-rich water produced when pyrite and other sulphides oxidise; each mole of pyrite releases four moles of H⁺."},
 {"id": "L2-g-advanced-argillic", "lecture": 2, "kind": "term", "front": "Advanced argillic", "back": "Very acidic alteration: quartz, alunite, pyrophyllite, dickite, diaspore, opaline silica."},
 {"id": "L2-g-alteration", "lecture": 2, "kind": "term", "front": "Alteration", "back": "A mineralogical change at low pressure caused by fluids moving through a rock, or by oxygen."},
 {"id": "L2-g-alteration-index", "lecture": 2, "kind": "term", "front": "Alteration index", "back": "AI = 100(K₂O+MgO)/(K₂O+MgO+Na₂O+CaO). Higher means more altered."},
 {"id": "L2-g-argillic", "lecture": 2, "kind": "term", "front": "Argillic", "back": "Clay alteration: kaolinite, dickite, illite, montmorillonite."},
 {"id": "L2-g-bauxite", "lecture": 2, "kind": "term", "front": "Bauxite", "back": "Aluminium ore formed by intense tropical weathering; mostly gibbsite."},
 {"id": "L2-g-bleaching", "lecture": 2, "kind": "term", "front": "Bleaching", "back": "Loss of colour as iron and other colouring elements are removed, leaving pale rock enriched in Si and Al."},
 {"id": "L2-g-boxwork", "lecture": 2, "kind": "term", "front": "Boxwork", "back": "Gossan texture where goethite fills cells left by dissolved sulphide crystals, preserving their shapes."},
 {"id": "L2-g-ccpi", "lecture": 2, "kind": "term", "front": "CCPI", "back": "Chlorite-carbonate-pyrite index = 100(MgO+FeO)/(MgO+FeO+Na₂O+K₂O)."},
 {"id": "L2-g-chalcocite", "lecture": 2, "kind": "term", "front": "Chalcocite", "back": "Cu₂S, about 80% copper. The classic supergene enrichment mineral."},
 {"id": "L2-g-cryptic-alteration", "lecture": 2, "kind": "term", "front": "Cryptic alteration", "back": "Alteration you can only detect chemically or isotopically, with no visible mineral change."},
 {"id": "L2-g-footwall", "lecture": 2, "kind": "term", "front": "Footwall", "back": "The rock below an orebody. In VMS systems, where most of the alteration sits."},
 {"id": "L2-g-gibbsite", "lecture": 2, "kind": "term", "front": "Gibbsite", "back": "Aluminium hydroxide, Al(OH)₃, the main mineral in bauxite."},
 {"id": "L2-g-goethite", "lecture": 2, "kind": "term", "front": "Goethite", "back": "Iron oxyhydroxide, FeO(OH). Brown-orange. Contains hydrogen, so it marks where water pooled, such as a water table."},
 {"id": "L2-g-gossan", "lecture": 2, "kind": "term", "front": "Gossan", "back": "The oxidised, iron-rich cap on a sulphide body, mostly goethite and hematite. May or may not overlie ore."},
 {"id": "L2-g-heap-leaching", "lecture": 2, "kind": "term", "front": "Heap leaching", "back": "Crushing ore, stacking it on a pad and percolating acid through it to dissolve and recover metal."},
 {"id": "L2-g-hematite", "lecture": 2, "kind": "term", "front": "Hematite", "back": "Iron oxide, Fe₂O₃. Red. Rule of thumb: forms where water flows and oxygen is plentiful."},
 {"id": "L2-g-immobile-elements", "lecture": 2, "kind": "term", "front": "Immobile elements", "back": "Elements that stay put during weathering and alteration: Si (mostly), Al, Ti, Zr, Y, Cr. Used to identify the original rock."},
 {"id": "L2-g-jarosite", "lecture": 2, "kind": "term", "front": "Jarosite", "back": "Potassium iron sulphate group minerals from acidic weathering of sulphides."},
 {"id": "L2-g-kaolinite", "lecture": 2, "kind": "term", "front": "Kaolinite", "back": "The most common clay formed by weathering of feldspar; also called kaolin."},
 {"id": "L2-g-karst", "lecture": 2, "kind": "term", "front": "Karst", "back": "Landscape of caves and sinkholes formed by dissolution of limestone."},
 {"id": "L2-g-laterite", "lecture": 2, "kind": "term", "front": "Laterite", "back": "A deeply weathered, iron- and aluminium-rich profile formed under hot, wet tropical conditions."},
 {"id": "L2-g-leached-zone", "lecture": 2, "kind": "term", "front": "Leached zone", "back": "The part of a weathered profile from which metals have been dissolved and removed."},
 {"id": "L2-g-mobile-elements", "lecture": 2, "kind": "term", "front": "Mobile elements", "back": "Elements easily dissolved and carried away by water or hydrothermal fluid: Na, K, Ca, Mg, Fe, Sr and many metals."},
 {"id": "L2-g-oxidation", "lecture": 2, "kind": "term", "front": "Oxidation", "back": "Loss of electrons. In ore deposits, the conversion of sulphides and carbonates to oxides and hydroxides by oxygenated water."},
 {"id": "L2-g-oxide-zone", "lecture": 2, "kind": "term", "front": "Oxide zone", "back": "The zone above the water table where metals sit in oxide, carbonate and silicate minerals such as malachite and azurite."},
 {"id": "L2-g-pearce-element-ratios", "lecture": 2, "kind": "term", "front": "Pearce element ratios", "back": "Molar ratios of mobile elements divided by a conserved element (usually Al) to track mass gain and loss."},
 {"id": "L2-g-phyllic", "lecture": 2, "kind": "term", "front": "Phyllic", "back": "Alteration to quartz, sericite (fine muscovite) and pyrite; also called sericitic."},
 {"id": "L2-g-potassic", "lecture": 2, "kind": "term", "front": "Potassic", "back": "Alteration adding potassium: K-feldspar, biotite, quartz, often magnetite. The hot core of porphyries."},
 {"id": "L2-g-propylitic", "lecture": 2, "kind": "term", "front": "Propylitic", "back": "Green, distal alteration: chlorite, epidote, albite, carbonate, pyrite."},
 {"id": "L2-g-protolith", "lecture": 2, "kind": "term", "front": "Protolith", "back": "The original rock before weathering, alteration or metamorphism."},
 {"id": "L2-g-pxrf", "lecture": 2, "kind": "term", "front": "PXRF", "back": "Portable X-ray fluorescence. Great for Cu, Pb, Zn; poor for REE, weak for Ag, useless for Au."},
 {"id": "L2-g-reduction", "lecture": 2, "kind": "term", "front": "Reduction", "back": "Gain of electrons. Sulphides form and stay stable in reduced conditions, below the water table."},
 {"id": "L2-g-residual-enrichment", "lecture": 2, "kind": "term", "front": "Residual enrichment", "back": "An element becoming more concentrated simply because other components were removed around it."},
 {"id": "L2-g-sericite", "lecture": 2, "kind": "term", "front": "Sericite", "back": "Not a mineral: a field term for fine-grained white mica (muscovite) with quartz."},
 {"id": "L2-g-supergene-enrichment", "lecture": 2, "kind": "term", "front": "Supergene enrichment", "back": "Metals leached from above reprecipitating at the water table, where conditions change from oxidising to reducing."},
 {"id": "L2-g-vector", "lecture": 2, "kind": "term", "front": "Vector", "back": "Any measurable change (mineral, chemical, isotopic) that points the way towards ore."},
 {"id": "L2-g-water-table", "lecture": 2, "kind": "term", "front": "Water table", "back": "The top of the groundwater-saturated zone; the boundary between oxidising and reducing conditions."},
 {"id": "L2-g-weathering", "lecture": 2, "kind": "term", "front": "Weathering", "back": "Physical and chemical breakdown of rock at or near the Earth's surface, usually within a few tens of metres."},
 {"id": "L2-g-xrd", "lecture": 2, "kind": "term", "front": "XRD", "back": "X-ray diffraction: identifies minerals, especially fine-grained clays and micas, by their crystal structure."},
 {"id": "L2-cp1", "lecture": 2, "kind": "mc", "front": "All else equal, which rock weathers fastest?", "opts": ["A fine-grained quartzite", "A coarse-grained limestone", "A fine-grained quartz sandstone"], "ans": "A coarse-grained limestone", "back": "Calcite is soluble and coarse grains expose more surface along their boundaries. Quartz barely reacts at all."},
 {"id": "L2-cp2", "lecture": 2, "kind": "mc", "front": "You find goethite rather than hematite in an oxidised zone. The best interpretation is...", "opts": ["Water pooled there, likely at an old water table", "It was extremely dry", "The rock was never oxidised"], "ans": "Water pooled there, likely at an old water table", "back": "Goethite contains hydrogen, so it needs water sitting around. Hematite points to flowing water and free oxygen."},
 {"id": "L2-cp3", "lecture": 2, "kind": "mc", "front": "A huge gossan in central NSW is drilled, and the sulphides underneath are just massive pyrite with no metals. What went wrong?", "opts": ["The drill missed the water table", "Nothing: gossans often form over barren pyrite or pyrrhotite", "Gold was eroded from the gossan"], "ans": "Nothing: gossans often form over barren pyrite or pyrrhotite", "back": "A gossan only tells you sulphides were there. Many big gossans are goethite replacing barren iron sulphides. Assays and boxwork textures tell you whether it’s worth chasing."},
 {"id": "L2-cp4", "lecture": 2, "kind": "mc", "front": "In a weathered copper deposit, where is copper usually most concentrated?", "opts": ["The leached zone", "The supergene blanket at the water table", "The gossan at the surface"], "ans": "The supergene blanket at the water table", "back": "The water table is the oxidation-reduction boundary. Copper leached from above reprecipitates there as chalcocite, covellite and bornite."},
 {"id": "L2-cp5", "lecture": 2, "kind": "mc", "front": "You drill through fresh chalcopyrite at 80 m, then hit native copper at 108 m. The most likely cause is...", "opts": ["A second, deeper oxide zone along a fault", "The rock got hotter with depth", "A drilling contamination error"], "ans": "A second, deeper oxide zone along a fault", "back": "Oxygenated water travelling down a fault can oxidise rock far below the normal oxide zone, as at Drake and Tsumeb."},
 {"id": "L2-cp6", "lecture": 2, "kind": "mc", "front": "A quartz-sericite rock contains 10% pyrite. That pyrite is probably...", "opts": ["The ore, so drill it out", "Part of the phyllic pyrite shell, not necessarily ore", "A weathering product"], "ans": "Part of the phyllic pyrite shell, not necessarily ore", "back": "Around porphyries, phyllic alteration carries a pyrite shell of about 10% pyrite with no copper. The ore shell is further in."},
 {"id": "L2-cp7", "lecture": 2, "kind": "mc", "front": "A sample has AI 88 and CCPI 94 with only 0.1% Na2O. What does that suggest?", "opts": ["Fresh basalt", "Intense chlorite-pyrite alteration close to ore", "Weak distal propylitic alteration"], "ans": "Intense chlorite-pyrite alteration close to ore", "back": "High AI and CCPI with sodium stripped out is exactly the Cowley Hills ore-zone signature."},
 {"id": "L2-cp8", "lecture": 2, "kind": "mc", "front": "Why is alteration a poor long-range vector for most hydrothermal vein deposits?", "opts": ["Veins never have alteration", "The alteration is narrow, usually under a metre wide", "Veins are always too deep"], "ans": "The alteration is narrow, usually under a metre wide", "back": "Vein deposits typically have narrow, discrete bleached zones a few centimetres to a metre wide, so there’s no big halo to follow."},
 {"id": "L2-cp9", "lecture": 2, "kind": "mc", "front": "Which of the three processes can happen kilometres below the surface, wherever fluids go?", "opts": ["Weathering", "Oxidation", "Alteration"], "ans": "Alteration", "back": "Weathering and oxidation work from the top down and stop around the water table, unless a structure lets oxygenated water go deeper."},
 {"id": "L2-cp10", "lecture": 2, "kind": "mc", "front": "Why does every mineral in the weathered-rock table survive?", "opts": ["They are end products, resistant to any further breakdown", "They all formed at high temperature", "They are all sulphides"], "ans": "They are end products, resistant to any further breakdown", "back": "Quartz, kaolinite, hematite, goethite, gibbsite, anatase: what’s left once everything mobile has gone."},
 {"id": "L2-cp11", "lecture": 2, "kind": "mc", "front": "Why is alteration the most commonly used vector to ore?", "opts": ["It is always ore grade", "The halo is far bigger than the ore, up to about two kilometres around a porphyry", "It is easy to date"], "ans": "The halo is far bigger than the ore, up to about two kilometres around a porphyry", "back": "A bigger target is easier to find, and its zoning points inwards."},
 {"id": "L2-cp12", "lecture": 2, "kind": "mc", "front": "In a porphyry district, why shouldn’t you only look for the porphyry itself?", "opts": ["Porphyries never carry copper", "Distal Cu-Pb-Zn-Ag-Au veins sit out in the propylitic zone", "The potassic core is always the richest ore"], "ans": "Distal Cu-Pb-Zn-Ag-Au veins sit out in the propylitic zone", "back": "The propylitic halo is wide, and it can host its own veins worth mining."},
 {"id": "L2-st1", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "Why does chemical weathering make dark rocks pale?", "back": "It removes iron, the main colouring element, along with other mobile elements. What’s left is enriched in silicon and aluminium, which make pale minerals like kaolinite and quartz. That’s bleaching."},
 {"id": "L2-st2", "lecture": 2, "kind": "q", "lvl": "Calculate", "front": "A basalt with 15 wt% Al2O3 loses half its mass to weathering but keeps all its aluminium. What’s the new Al2O3 grade?", "back": "15 g of Al2O3 now sits in 50 g of rock, so 30 wt%. A concentration factor of 2 from subtraction alone."},
 {"id": "L2-st3", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "Give three reasons weathered rock matters to a mining company, one good and two bad.", "back": "Good: it can form ore (bauxite, supergene enrichment, oxide zones) and gossans can point to ore. Bad: it masks the geology underneath, usually carries nothing economic and must be stripped before open-cut mining, and it’s weak, causing engineering problems."},
 {"id": "L2-st4", "lecture": 2, "kind": "q", "lvl": "Apply", "front": "Write the overall effect of oxidising one mole of pyrite in terms of acid, and explain why carbonate host rocks reduce the problem.", "back": "Four moles of H⁺ are released per mole of FeS2, plus iron hydroxide. Carbonate minerals react with and neutralise H⁺, so carbonate-rich rock buffers the acid; quartz-rich rock can’t."},
 {"id": "L2-st5", "lecture": 2, "kind": "q", "lvl": "Think", "front": "Explain why the supergene blanket forms exactly at the water table.", "back": "Above the water table, oxygenated water dissolves copper from sulphides. Below it, conditions are reducing. When copper-bearing water reaches the reducing zone, copper reprecipitates as Cu-rich sulphides like chalcocite. The water table is that redox boundary."},
 {"id": "L2-st6", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "Why might a mine stockpile native copper instead of feeding it to the crusher?", "back": "Native copper is soft and malleable. It smears and jams crushers rather than breaking. It also consumes acid in heap leaching. Mines often stockpile it and blend it slowly with lower-grade ore."},
 {"id": "L2-st7", "lecture": 2, "kind": "q", "lvl": "Apply", "front": "A porphyry explorer finds green rock with 2% pyrite, then pale rock with 10% pyrite. Which way should they go next, and what are they hoping to find?", "back": "Further in the direction that took them from propylitic to phyllic, but carefully: just inside the phyllic pyrite shell is the ore shell with 1 to 3% chalcopyrite. Overshoot and you’re in the potassic, low-grade core."},
 {"id": "L2-st8", "lecture": 2, "kind": "q", "lvl": "Recall", "front": "In a VMS footwall, how does chlorite change as you approach the ore, and how could you see that in core?", "back": "It goes from magnesium-rich (nearly colourless) far out to iron-rich (deep green) near the ore and feeder zone. The colour change is visible in hand specimen."},
 {"id": "L2-st9", "lecture": 2, "kind": "q", "lvl": "Think", "front": "Why divide strontium by titanium rather than just using Sr?", "back": "Titanium is immobile, so it stays constant through alteration. Dividing by it cancels out changes in rock type or mass, so a falling Sr/Ti really means strontium was stripped by fluid, not that you drilled into a different rock."},
 {"id": "L2-st10", "lecture": 2, "kind": "q", "lvl": "Apply", "front": "Your pXRF shows no gold in a gossan sample with visible gold. What happened?", "back": "Nothing is wrong with the gossan. pXRF is no good for gold. Send samples for proper laboratory assay (fire assay) when gold is the target."},
 /* Lecture 3: 37 terms, 13 checkpoints, 10 self-test */
 {"id": "L3-g-breccia", "lecture": 3, "kind": "term", "front": "Breccia", "back": "Broken rock: angular fragments (clasts) in a finer-grained matrix or cement."},
 {"id": "L3-g-cement", "lecture": 3, "kind": "term", "front": "Cement", "back": "Minerals that precipitated from fluid in the spaces between clasts, binding them together."},
 {"id": "L3-g-chaotic-breccia", "lecture": 3, "kind": "term", "front": "Chaotic breccia", "back": "Fault breccia with strongly rotated clasts that no longer fit; 30 to 60% large clasts."},
 {"id": "L3-g-chert-breccia", "lecture": 3, "kind": "term", "front": "Chert breccia", "back": "Breccia where both clasts and matrix are microcrystalline quartz, formed as quartz replaced carbonate during diagenesis."},
 {"id": "L3-g-clast", "lecture": 3, "kind": "term", "front": "Clast", "back": "A fragment of rock or mineral within a breccia or sediment."},
 {"id": "L3-g-comb-quartz", "lecture": 3, "kind": "term", "front": "Comb quartz", "back": "Quartz crystals grown from vein walls into open space, with euhedral terminations pointing inwards."},
 {"id": "L3-g-crack-seal", "lecture": 3, "kind": "term", "front": "Crack-seal", "back": "Repeated cracking and sealing of a vein, building many thin laminations."},
 {"id": "L3-g-crackle-breccia", "lecture": 3, "kind": "term", "front": "Crackle breccia", "back": "Fault breccia with minimal clast rotation; 75 to 100% large clasts."},
 {"id": "L3-g-disseminated-ore", "lecture": 3, "kind": "term", "front": "Disseminated ore", "back": "Ore with less than 10% ore minerals, scattered through the host."},
 {"id": "L3-g-durchbewegung", "lecture": 3, "kind": "term", "front": "Durchbewegung", "back": "Texture of rigid, rotated clasts in a ductile sulphide matrix, formed by deformation of sulphide ore."},
 {"id": "L3-g-effective-stress", "lecture": 3, "kind": "term", "front": "Effective stress", "back": "Confining stress minus fluid pressure. When it approaches zero, rock fractures easily."},
 {"id": "L3-g-epiclastic", "lecture": 3, "kind": "term", "front": "Epiclastic", "back": "Volcanic fragments transported by water or gravity, such as lahars and debris flows."},
 {"id": "L3-g-extensional-vein", "lecture": 3, "kind": "term", "front": "Extensional vein", "back": "Planar vein formed by simple pulling apart, with crystals grown perpendicular to the walls."},
 {"id": "L3-g-ginguro", "lecture": 3, "kind": "term", "front": "Ginguro", "back": "Japanese term for laminated epithermal veins with sooty black sulphide bands rich in gold and silver."},
 {"id": "L3-g-hyaloclastite", "lecture": 3, "kind": "term", "front": "Hyaloclastite", "back": "Glassy breccia formed when lava quenches and shatters against water."},
 {"id": "L3-g-hydrofracturing", "lecture": 3, "kind": "term", "front": "Hydrofracturing", "back": "Fracturing caused when fluid pressure exceeds the confining stress plus the rock's tensile strength."},
 {"id": "L3-g-jig-saw-breccia", "lecture": 3, "kind": "term", "front": "Jig-saw breccia", "back": "Breccia formed by dilation with almost no rotation, so the clasts fit back together."},
 {"id": "L3-g-magmatic-breccia", "lecture": 3, "kind": "term", "front": "Magmatic breccia", "back": "Breccia formed when a crystallising, still-plastic magma fractures, often from volatile exsolution."},
 {"id": "L3-g-massive-ore", "lecture": 3, "kind": "term", "front": "Massive ore", "back": "Ore with more than 50% ore minerals."},
 {"id": "L3-g-matrix", "lecture": 3, "kind": "term", "front": "Matrix", "back": "The finer-grained material between clasts. Can be fragmental (rock flour) or crystalline."},
 {"id": "L3-g-mosaic-breccia", "lecture": 3, "kind": "term", "front": "Mosaic breccia", "back": "Fault breccia with more separation and rotation; 60 to 75% large clasts."},
 {"id": "L3-g-mvt", "lecture": 3, "kind": "term", "front": "MVT", "back": "Mississippi Valley type: carbonate-hosted lead-zinc deposits, often in solution-collapse breccias."},
 {"id": "L3-g-net-textured", "lecture": 3, "kind": "term", "front": "Net-textured", "back": "Sulphide forming a connected network between silicate grains, typical of magmatic nickel ores."},
 {"id": "L3-g-peperite", "lecture": 3, "kind": "term", "front": "Peperite", "back": "Breccia of magma mixed with wet, unconsolidated sediment it intruded."},
 {"id": "L3-g-phreatic-breccia", "lecture": 3, "kind": "term", "front": "Phreatic breccia", "back": "Breccia formed by steam explosions when magma heats groundwater; mostly country rock clasts."},
 {"id": "L3-g-pseudotachylite", "lecture": 3, "kind": "term", "front": "Pseudotachylite", "back": "Glassy rock formed by near-instant frictional or shock melting, as in impact structures. Literally 'false glass'."},
 {"id": "L3-g-remobilisation", "lecture": 3, "kind": "term", "front": "Remobilisation", "back": "Physical and chemical movement and recrystallisation of ore minerals during metamorphism and deformation."},
 {"id": "L3-g-rip-up-clasts", "lecture": 3, "kind": "term", "front": "Rip-up clasts", "back": "Fragments of partly lithified sediment torn up by a later current and deposited in a younger layer."},
 {"id": "L3-g-rock-flour", "lecture": 3, "kind": "term", "front": "Rock flour", "back": "Rock ground to fine powder by fault movement or explosive fluid release."},
 {"id": "L3-g-semi-massive-ore", "lecture": 3, "kind": "term", "front": "Semi-massive ore", "back": "Ore with 10 to 50% ore minerals."},
 {"id": "L3-g-skarn", "lecture": 3, "kind": "term", "front": "Skarn", "back": "Calc-silicate rock (garnet, pyroxene, wollastonite) formed by hot fluids reacting with carbonate-bearing rock."},
 {"id": "L3-g-slickenlines", "lecture": 3, "kind": "term", "front": "Slickenlines", "back": "Lineations on a fault surface showing the direction of movement."},
 {"id": "L3-g-solution-collapse-breccia", "lecture": 3, "kind": "term", "front": "Solution-collapse breccia", "back": "Breccia formed when overlying rock collapses into space left by dissolved evaporite or carbonate. Hosts many MVT deposits."},
 {"id": "L3-g-space-fill-vein", "lecture": 3, "kind": "term", "front": "Space-fill vein", "back": "Zoned vein that only partly filled at first, leaving open space for later minerals."},
 {"id": "L3-g-stockwork", "lecture": 3, "kind": "term", "front": "Stockwork", "back": "A network of many crossing and subparallel veins in a small volume of rock."},
 {"id": "L3-g-syngenetic", "lecture": 3, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host rock, as in banded SEDEX and VMS ores."},
 {"id": "L3-g-vein", "lecture": 3, "kind": "term", "front": "Vein", "back": "A fracture that was dilated and filled with minerals."},
 {"id": "L3-cp1", "lecture": 3, "kind": "mc", "front": "A carbonate-evaporite sequence shows V-shaped sags, a pipe of rubble with inward-dipping beds, and a sharp flat base. Which breccia is it?", "opts": ["Solution-collapse", "Impact", "Phreatic"], "ans": "Solution-collapse", "back": "All three are diagnostic of collapse into space left by dissolved evaporite or carbonate."},
 {"id": "L3-cp2", "lecture": 3, "kind": "mc", "front": "A fault breccia is 65% large clasts with some rotation, but you can still roughly fit pieces together. Classify it.", "opts": ["Crackle", "Mosaic", "Chaotic"], "ans": "Mosaic", "back": "Mosaic breccias are 60 to 75% large clasts with moderate rotation."},
 {"id": "L3-cp3", "lecture": 3, "kind": "mc", "front": "Rounded host-rock clasts sit in a sulphide matrix that was itself a melt. Which breccia type?", "opts": ["Hydrothermal", "Magmatic", "Epiclastic"], "ans": "Magmatic", "back": "A molten sulphide matrix with rounded clasts is magmatic, as at Sudbury."},
 {"id": "L3-cp4", "lecture": 3, "kind": "mc", "front": "A hand specimen is about 25% sphalerite and galena. How do you classify it?", "opts": ["Massive", "Semi-massive", "Disseminated"], "ans": "Semi-massive", "back": "10 to 50% ore minerals is semi-massive."},
 {"id": "L3-cp5", "lecture": 3, "kind": "mc", "front": "In a laminated crack-seal vein, where is the youngest material?", "opts": ["At the walls", "At the centre", "Randomly spread"], "ans": "At the centre", "back": "The centre is the weakest plane and keeps reopening, so the walls crystallise first and the centre last."},
 {"id": "L3-cp6", "lecture": 3, "kind": "mc", "front": "Vein A is offset by vein B, and both are cut, without offset, by vein C. What’s the order?", "opts": ["A, B, C", "C, B, A", "B, A, C"], "ans": "A, B, C", "back": "Offset features are older than what offsets them, and the unbroken cross-cutter is youngest."},
 {"id": "L3-cp7", "lecture": 3, "kind": "mc", "front": "Rigid quartz clasts rotated inside fine-grained galena in a deformed ore. What is this texture?", "opts": ["Jig-saw breccia", "Durchbewegung", "Crackle breccia"], "ans": "Durchbewegung", "back": "Durchbewegung: brittle clasts rolled in a ductile sulphide matrix during deformation."},
 {"id": "L3-cp8", "lecture": 3, "kind": "mc", "front": "In the Tuena goldfield an honours project found five generations of veins. Why did telling them apart matter?", "opts": ["Only the last generation carried the gold", "Every generation had the same grade", "They were all the same age"], "ans": "Only the last generation carried the gold", "back": "Textures carry timing: if you can’t tell the veins apart, you can’t tell which one to follow."},
 {"id": "L3-cp9", "lecture": 3, "kind": "mc", "front": "Which three observations let you work out what broke a breccia?", "opts": ["Colour, hardness and lustre", "Clast shape and sorting, how far the clasts moved and rotated, and what the matrix is", "Matrix grain size only"], "ans": "Clast shape and sorting, how far the clasts moved and rotated, and what the matrix is", "back": "Work backwards from those three to one of the six breaking agents."},
 {"id": "L3-cp10", "lecture": 3, "kind": "mc", "front": "Why do hydrothermal breccias form more easily near the surface?", "opts": ["Rock is stronger there", "Confining stress is low, so less fluid pressure is needed to drive effective stress to zero", "There’s no fluid at depth"], "ans": "Confining stress is low, so less fluid pressure is needed to drive effective stress to zero", "back": "Effective stress is confining stress minus fluid pressure; near the surface there’s less confinement to beat."},
 {"id": "L3-cp11", "lecture": 3, "kind": "mc", "front": "A breccia’s clasts still fit together like a jigsaw, separated by quartz fill, and haven’t rotated. What does that tell you?", "opts": ["They were carried far by a debris flow", "The rock fractured and dilated in place with almost no movement", "It’s an impact breccia"], "ans": "The rock fractured and dilated in place with almost no movement", "back": "Jig-saw texture means fracturing and dilation only."},
 {"id": "L3-cp12", "lecture": 3, "kind": "mc", "front": "Gold ore is usually which abundance class, and why is it still mined?", "opts": ["Massive, because gold is dense", "Disseminated, because gold is so valuable that low concentrations pay", "Semi-massive, because it forms bands"], "ans": "Disseminated, because gold is so valuable that low concentrations pay", "back": "What counts as economic depends on the commodity. At Thackaringa, disseminated pyrite is the target because it carries cobalt."},
 {"id": "L3-cp13", "lecture": 3, "kind": "mc", "front": "You log three sphalerite bands: honey-yellow, red and black. What’s changing?", "opts": ["Grain size", "Iron content, from low to high", "How weathered it is"], "ans": "Iron content, from low to high", "back": "Sphalerite takes iron into its structure; the darker, the more iron."},
 {"id": "L3-st1", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "What three observations let you work out what broke a breccia?", "back": "Clast shape and sorting (angular or rounded, sorted or not), how much the clasts moved and rotated (do they still fit?), and what the matrix or cement is (rock flour, quartz, sulphide, melt, glass)."},
 {"id": "L3-st2", "lecture": 3, "kind": "q", "lvl": "Think", "front": "Why are solution-collapse breccias good hosts for MVT ore?", "back": "Collapse creates a pipe of permeable rubble with lots of open space. Later basin brines can flow through it and precipitate galena and sphalerite between the blocks."},
 {"id": "L3-st3", "lecture": 3, "kind": "q", "lvl": "Apply", "front": "Explain hydrofracturing in terms of effective stress, and why it’s easier near the surface.", "back": "Effective stress is confining stress minus fluid pressure. As fluid pressure rises, effective stress falls; once fluid pressure exceeds confining stress plus tensile strength, the rock fractures. Near the surface the confining stress is much lower, so less fluid pressure is needed, and sudden depressurisation can make it explosive."},
 {"id": "L3-st4", "lecture": 3, "kind": "q", "lvl": "Think", "front": "How would you tell a debris flow breccia from a hydrothermal breccia in the field?", "back": "A debris flow is extremely poorly sorted, has a surface, gravity-driven origin and no hydrothermal cement or alteration. A hydrothermal breccia has altered clasts and a precipitated cement (quartz, carbonate, sulphide) or milled rock flour from fluid action."},
 {"id": "L3-st5", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "Why are banded ores strong evidence for syngenetic deposition?", "back": "Continuous ore-mineral bands parallel to bedding mean the sulphide accumulated layer by layer with the host sediment, as on the floor of a SEDEX basin or around VMS vents."},
 {"id": "L3-st6", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "List the five things you should record when describing a vein.", "back": "Geometry (planar, sinuous), width and spacing, continuity, orientation relative to bedding or structures, and mineralogy."},
 {"id": "L3-st7", "lecture": 3, "kind": "q", "lvl": "Apply", "front": "A vein has comb quartz along both walls and molybdenite in the centre. What type is it, and what’s the sequence?", "back": "A space-fill vein. Quartz grew first from the walls into open space (euhedral points inward), then molybdenite filled the remaining cavity."},
 {"id": "L3-st8", "lecture": 3, "kind": "q", "lvl": "Think", "front": "Why do companies get excited about stockwork veins in a porphyry?", "back": "A stockwork means intense, repeated hydrofracturing and many mineralising pulses through a large volume of rock: the bulk, low-grade but enormous tonnage that porphyries are mined for."},
 {"id": "L3-st9", "lecture": 3, "kind": "q", "lvl": "Recall", "front": "What’s the easiest field clue that an ore has been remobilised by metamorphism?", "back": "Coarse grain size compared with the original fine sulphides, often with strained or ribbon-like galena."},
 {"id": "L3-st10", "lecture": 3, "kind": "q", "lvl": "Think", "front": "Why does durchbewegung texture need both brittle and ductile materials?", "back": "The brittle material (siliceous host or quartz) breaks into clasts, and the ductile sulphide (galena, sphalerite) flows around them, letting the clasts rotate. If everything were ductile you’d get smearing; if everything were brittle you’d get cataclasis."},
 /* Lecture 4: 30 terms, 8 checkpoints, 10 self-test */
 {"id": "L4-g-anisotropy", "lecture": 4, "kind": "term", "front": "Anisotropy", "back": "Showing colours and four extinction positions per rotation under crossed polars."},
 {"id": "L4-g-bireflectance", "lecture": 4, "kind": "term", "front": "Bireflectance", "back": "A change in brightness of a grain as the stage is rotated in PPL."},
 {"id": "L4-g-bireflectance-pleochroism", "lecture": 4, "kind": "term", "front": "Bireflectance pleochroism", "back": "A change in colour of a grain as the stage is rotated in PPL. Extreme in covellite."},
 {"id": "L4-g-caries-texture", "lecture": 4, "kind": "term", "front": "Caries texture", "back": "Embayed, eaten-away margins of an early mineral replaced by a later one. Also called atoll texture."},
 {"id": "L4-g-chalcopyrite-disease", "lecture": 4, "kind": "term", "front": "Chalcopyrite disease", "back": "Tiny chalcopyrite blebs in sphalerite, usually from later replacement rather than exsolution."},
 {"id": "L4-g-conchoidal-fracture", "lecture": 4, "kind": "term", "front": "Conchoidal fracture", "back": "Curved, shell-like fractures, typical of chromite in polished section."},
 {"id": "L4-g-crossed-polars", "lecture": 4, "kind": "term", "front": "Crossed polars", "back": "Both polariser and analyser in (XPL or UXP). Used to test anisotropy and see internal reflections."},
 {"id": "L4-g-cuspate-lobate", "lecture": 4, "kind": "term", "front": "Cuspate-lobate", "back": "Smooth, mutually indented grain boundaries indicating two minerals grew together."},
 {"id": "L4-g-euhedral", "lecture": 4, "kind": "term", "front": "Euhedral", "back": "Bounded by its own crystal faces."},
 {"id": "L4-g-exsolution-lamellae", "lecture": 4, "kind": "term", "front": "Exsolution lamellae", "back": "Thin oriented plates of one mineral unmixed from another on cooling, like chalcopyrite in bornite."},
 {"id": "L4-g-framboid", "lecture": 4, "kind": "term", "front": "Framboid", "back": "A spherical cluster of tiny pyrite (or galena) crystals; often biogenic, but can be hydrothermal."},
 {"id": "L4-g-free-gold", "lecture": 4, "kind": "term", "front": "Free gold", "back": "Gold present as discrete grains that can be recovered by gravity or simple leaching."},
 {"id": "L4-g-grain-mount", "lecture": 4, "kind": "term", "front": "Grain mount", "back": "Loose grains (concentrate, crushed ore) set in resin and polished."},
 {"id": "L4-g-gravity-separation", "lecture": 4, "kind": "term", "front": "Gravity separation", "back": "Recovering dense minerals like free gold by their density difference from the rest of the ore."},
 {"id": "L4-g-internal-reflections", "lecture": 4, "kind": "term", "front": "Internal reflections", "back": "Coloured light bouncing back from inside a semi-transparent grain via fractures. Classic in sphalerite."},
 {"id": "L4-g-isotropic", "lecture": 4, "kind": "term", "front": "Isotropic", "back": "Staying dark under crossed polars at every rotation. Cubic minerals are isotropic, except pyrite."},
 {"id": "L4-g-mineragraphy", "lecture": 4, "kind": "term", "front": "Mineragraphy", "back": "Ore microscopy: the study of ore minerals in polished section under reflected light."},
 {"id": "L4-g-opaque-mineral", "lecture": 4, "kind": "term", "front": "Opaque mineral", "back": "A mineral that absorbs transmitted light, such as most sulphides and oxides."},
 {"id": "L4-g-paragenesis", "lecture": 4, "kind": "term", "front": "Paragenesis", "back": "The order in which minerals crystallised in a deposit, often drawn as a chart."},
 {"id": "L4-g-penalty-elements", "lecture": 4, "kind": "term", "front": "Penalty elements", "back": "Elements such as arsenic and tellurium that smelters charge extra to deal with in concentrate."},
 {"id": "L4-g-polished-block", "lecture": 4, "kind": "term", "front": "Polished block", "back": "A sample set in resin and polished on one face for reflected light."},
 {"id": "L4-g-polished-thin-section", "lecture": 4, "kind": "term", "front": "Polished thin section", "back": "A 30 µm section polished on top, usable in both transmitted and reflected light."},
 {"id": "L4-g-polishing-hardness", "lecture": 4, "kind": "term", "front": "Polishing hardness", "back": "Relative hardness seen in polished section: hard grains stand proud with crisp edges, soft ones scratch."},
 {"id": "L4-g-porphyroblast", "lecture": 4, "kind": "term", "front": "Porphyroblast", "back": "A large crystal grown within a finer matrix, often enclosing inclusions of earlier minerals."},
 {"id": "L4-g-ppl", "lecture": 4, "kind": "term", "front": "PPL", "back": "Plane-polarised light: one polariser in. Used for colour, reflectance and bireflectance."},
 {"id": "L4-g-reflectance", "lecture": 4, "kind": "term", "front": "Reflectance", "back": "How much light a polished surface reflects; judge it relative to neighbouring grains."},
 {"id": "L4-g-reflected-light", "lecture": 4, "kind": "term", "front": "Reflected light", "back": "Illumination that comes down through the objective and reflects off a polished surface, used for opaque minerals."},
 {"id": "L4-g-refractory-gold", "lecture": 4, "kind": "term", "front": "Refractory gold", "back": "Gold locked inside sulphides such as pyrite or arsenopyrite, needing extra processing to recover."},
 {"id": "L4-g-tarnish", "lecture": 4, "kind": "term", "front": "Tarnish", "back": "A surface colour change after polishing: purple on bornite, bluish on chalcocite."},
 {"id": "L4-g-triangular-pits", "lecture": 4, "kind": "term", "front": "Triangular pits", "back": "Pits left where polishing plucks out cleavage fragments; diagnostic of galena."},
 {"id": "L4-cp1", "lecture": 4, "kind": "mc", "front": "Why should you report arsenic- and tellurium-bearing minerals in an ore?", "opts": ["They raise the grade", "Smelters penalise them and they can harm the environment", "They make the ore easier to grind"], "ans": "Smelters penalise them and they can harm the environment", "back": "Dirty minerals cost money at the smelter and can be environmental hazards, so you want to know about them early."},
 {"id": "L4-cp2", "lecture": 4, "kind": "mc", "front": "Under crossed polars a grain stays completely black as you rotate the stage. It is...", "opts": ["Isotropic, like galena", "Strongly anisotropic", "Showing internal reflections"], "ans": "Isotropic, like galena", "back": "Isotropic minerals stay dark at every angle under crossed polars. Cubic minerals are isotropic, with pyrite as the exception."},
 {"id": "L4-cp3", "lecture": 4, "kind": "mc", "front": "Pyrite looks bright next to sphalerite but dull next to galena. Which property are you misjudging?", "opts": ["Hardness", "Reflectance, which you must judge relative to neighbours", "Crystal system"], "ans": "Reflectance, which you must judge relative to neighbours", "back": "Perceived reflectance depends on what’s next to it. Always compare grains with their neighbours."},
 {"id": "L4-cp4", "lecture": 4, "kind": "mc", "front": "A galena inclusion in sphalerite has smooth, mutually indented boundaries. What does it mean?", "opts": ["Galena replaced sphalerite much later", "They co-crystallised", "Weathering"], "ans": "They co-crystallised", "back": "Cuspate-lobate boundaries with no cross-cutting are an equilibrium texture: the two grew together."},
 {"id": "L4-cp5", "lecture": 4, "kind": "mc", "front": "Bright white mineral, soft, isotropic, with triangular pits. Name it.", "opts": ["Arsenopyrite", "Galena", "Chalcocite"], "ans": "Galena", "back": "Triangular cleavage pits mean galena; nothing else common does that."},
 {"id": "L4-cp6", "lecture": 4, "kind": "mc", "front": "Why do ore minerals need reflected light rather than transmitted light?", "opts": ["They’re too soft to make thin sections", "They’re opaque: dense, heavy-element structures absorb the light, so you read the polished surface instead", "They’re colourless"], "ans": "They’re opaque: dense, heavy-element structures absorb the light, so you read the polished surface instead", "back": "A reflective surface turns the opacity problem into information."},
 {"id": "L4-cp7", "lecture": 4, "kind": "mc", "front": "A grain stays dark as you rotate it under crossed polars. What does that tell you?", "opts": ["It’s strongly anisotropic", "It’s isotropic, like galena or pentlandite", "It’s magnetic"], "ans": "It’s isotropic, like galena or pentlandite", "back": "Isotropic minerals stay dark on rotation; anisotropic ones change colour and brightness."},
 {"id": "L4-cp8", "lecture": 4, "kind": "mc", "front": "Where should you start when narrowing the identification key?", "opts": ["Hardness", "Colour, the easiest observation, then reflectance, anisotropy, hardness and internal reflections", "Internal reflections"], "ans": "Colour, the easiest observation, then reflectance, anisotropy, hardness and internal reflections", "back": "You don’t memorise nineteen descriptions; you eliminate."},
 {"id": "L4-st1", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "Why are most ore minerals studied in reflected rather than transmitted light?", "back": "They’re opaque: dense, heavy-element structures absorb transmitted light, so they look black in a thin section. A polished surface reflects light, revealing colour, reflectance and anisotropy."},
 {"id": "L4-st2", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "Give three reasons a mining company pays for ore microscopy.", "back": "Any three of: which mineral hosts the metal (free vs refractory gold); grain size for grinding and liberation; dirty minerals like As and Te that attract penalties; alteration minerals tied to ore for exploration; timing relationships for the deposit’s genesis."},
 {"id": "L4-st3", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "What’s the difference between bireflectance and bireflectance pleochroism?", "back": "Both are seen rotating the stage in PPL. Bireflectance is a change in brightness; bireflectance pleochroism is a change in colour."},
 {"id": "L4-st4", "lecture": 4, "kind": "q", "lvl": "Think", "front": "Pyrite is cubic. What’s unusual about it under crossed polars?", "back": "Cubic minerals should be isotropic, but pyrite is commonly weakly to strongly anisotropic. It’s the classic exception."},
 {"id": "L4-st5", "lecture": 4, "kind": "q", "lvl": "Apply", "front": "How would you tell pyrite, chalcopyrite and gold apart?", "back": "Pyrite: pale yellow, high reflectance, hard, perfect polish. Chalcopyrite: stronger yellow, softer, moderate reflectance. Gold: yellow-orange, extremely bright even with the lamp turned down, soft and poorly polished."},
 {"id": "L4-st6", "lecture": 4, "kind": "q", "lvl": "Apply", "front": "A grain is pink-brown with fine blue and yellow lamellae and a purple tarnish. Identify all three minerals.", "back": "Bornite (pink-brown, purple tarnish) with exsolution or replacement lamellae of chalcocite (blue) and chalcopyrite (yellow)."},
 {"id": "L4-st7", "lecture": 4, "kind": "q", "lvl": "Think", "front": "Why should you never build a paragenesis from one polished section?", "back": "A single section may miss key relationships, and the main ore event can be distinct from earlier and later events elsewhere in the deposit. You need many samples and to link observations across scales."},
 {"id": "L4-st8", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "What does a caries texture tell you about timing?", "back": "The embayed mineral (often pyrite) formed first and was partly dissolved and replaced by the mineral filling the embayments."},
 {"id": "L4-st9", "lecture": 4, "kind": "q", "lvl": "Recall", "front": "Why can’t you rely on magnetism to identify pyrrhotite?", "back": "Some pyrrhotite (monoclinic) is magnetic and some (hexagonal) isn’t. Use the bronze colour, strong anisotropy and quick oxidation instead."},
 {"id": "L4-st10", "lecture": 4, "kind": "q", "lvl": "Apply", "front": "A deposit’s gold is all refractory. What process step does the plant need that a free-gold plant doesn’t?", "back": "Something to break down the host sulphide before cyanide leaching or other recovery: roasting, pressure oxidation or bacterial oxidation."},
 /* Lecture 5: 31 terms, 8 checkpoints, 10 self-test */
 {"id": "L5-g-anticline", "lecture": 5, "kind": "term", "front": "Anticline", "back": "An upward-arched fold; its hinge can trap rising fluids under an impermeable cap."},
 {"id": "L5-g-aquitard", "lecture": 5, "kind": "term", "front": "Aquitard", "back": "A layer or structure that greatly slows fluid flow, such as a clay-rich fault gouge, shale or dyke."},
 {"id": "L5-g-bad-ground", "lecture": 5, "kind": "term", "front": "Bad ground", "back": "Weak, phyllosilicate-rich rock (talc, chlorite) along shear zones that is hard to support underground."},
 {"id": "L5-g-brittle-ductile-transition", "lecture": 5, "kind": "term", "front": "Brittle-ductile transition", "back": "The crustal depth where rocks switch from fracturing to flowing; a sweet spot for orogenic gold."},
 {"id": "L5-g-carlin-type-gold", "lecture": 5, "kind": "term", "front": "Carlin-type gold", "back": "Invisible, micron-scale gold replacing silty limestone along extensional faults, as in Nevada."},
 {"id": "L5-g-crustal-continuum", "lecture": 5, "kind": "term", "front": "Crustal continuum", "back": "The model that one orogenic gold system can deposit gold over a wide range of crustal depths."},
 {"id": "L5-g-decalcification", "lecture": 5, "kind": "term", "front": "Decalcification", "back": "Removal of carbonate from limestone by acidic fluid."},
 {"id": "L5-g-detachment-fault", "lecture": 5, "kind": "term", "front": "Detachment fault", "back": "A large, low-angle normal fault separating extended upper crust from the rocks below."},
 {"id": "L5-g-diapir", "lecture": 5, "kind": "term", "front": "Diapir", "back": "A body of buoyant rock (such as granite) that rises and pierces the rocks above."},
 {"id": "L5-g-en-echelon", "lecture": 5, "kind": "term", "front": "En echelon", "back": "A stepped array of parallel, overlapping structures such as tension gashes, typical of shear."},
 {"id": "L5-g-fault-gouge", "lecture": 5, "kind": "term", "front": "Fault gouge", "back": "Rock ground to clay-sized material along a fault; usually impermeable."},
 {"id": "L5-g-first-order-fault", "lecture": 5, "kind": "term", "front": "First-order fault", "back": "A crustal-scale fault tens to hundreds of kilometres long, acting as a fluid highway."},
 {"id": "L5-g-fold-hinge", "lecture": 5, "kind": "term", "front": "Fold hinge", "back": "The zone of maximum curvature in a fold; a zone of weakness and a common trap."},
 {"id": "L5-g-footwall", "lecture": 5, "kind": "term", "front": "Footwall", "back": "The block below an inclined fault or orebody."},
 {"id": "L5-g-greenstone-belt", "lecture": 5, "kind": "term", "front": "Greenstone belt", "back": "An Archaean belt of metamorphosed volcanic and sedimentary rocks, often gold-rich."},
 {"id": "L5-g-hanging-wall", "lecture": 5, "kind": "term", "front": "Hanging wall", "back": "The block above an inclined fault or orebody."},
 {"id": "L5-g-horst-and-graben", "lecture": 5, "kind": "term", "front": "Horst and graben", "back": "Uplifted (horst) and down-dropped (graben) blocks bounded by normal faults in extension."},
 {"id": "L5-g-jasperoid", "lecture": 5, "kind": "term", "front": "Jasperoid", "back": "Fine-grained silica that has replaced limestone, typical of Carlin-type alteration."},
 {"id": "L5-g-l-tectonite", "lecture": 5, "kind": "term", "front": "L-tectonite", "back": "A rock dominated by a stretching lineation, so it looks like a bundle of rods or pencils."},
 {"id": "L5-g-lineament", "lecture": 5, "kind": "term", "front": "Lineament", "back": "A linear feature in imagery or geophysics that may mark a fault or structural corridor."},
 {"id": "L5-g-normal-fault", "lecture": 5, "kind": "term", "front": "Normal fault", "back": "A fault where the hanging wall moves down relative to the footwall; forms under extension."},
 {"id": "L5-g-orogenic-gold", "lecture": 5, "kind": "term", "front": "Orogenic gold", "back": "Gold deposits formed by metamorphic fluids along shear zones in deforming mountain belts."},
 {"id": "L5-g-plane-of-weakness", "lecture": 5, "kind": "term", "front": "Plane of weakness", "back": "Any existing surface (bedding, contact, fault, foliation) that later stress will reactivate in preference to breaking fresh rock."},
 {"id": "L5-g-reactivation", "lecture": 5, "kind": "term", "front": "Reactivation", "back": "Renewed movement on an existing structure during a later deformation."},
 {"id": "L5-g-reverse-fault", "lecture": 5, "kind": "term", "front": "Reverse fault", "back": "A fault where the hanging wall moves up; forms under compression. A low-angle one is a thrust."},
 {"id": "L5-g-rheological-barrier", "lecture": 5, "kind": "term", "front": "Rheological barrier", "back": "A strong, rigid body (such as a granite) that deforms differently from its surroundings and blocks fluid."},
 {"id": "L5-g-rock-softening", "lecture": 5, "kind": "term", "front": "Rock softening", "back": "Weakening of competent rock by deformation plus fluid, often by growth of chlorite and talc."},
 {"id": "L5-g-saddle-reef", "lecture": 5, "kind": "term", "front": "Saddle reef", "back": "A quartz-gold body filling the gap opened between beds at an anticline hinge, as at Bendigo."},
 {"id": "L5-g-splay", "lecture": 5, "kind": "term", "front": "Splay", "back": "A smaller fault branching off a larger one. Second- and third-order splays often host orogenic gold."},
 {"id": "L5-g-strike-slip-fault", "lecture": 5, "kind": "term", "front": "Strike-slip fault", "back": "A fault with mainly horizontal movement parallel to its strike."},
 {"id": "L5-g-tension-gash", "lecture": 5, "kind": "term", "front": "Tension gash", "back": "A short vein opened by extension within a shear zone, often sigmoidal."},
 {"id": "L5-cp1", "lecture": 5, "kind": "mc", "front": "A fault cuts an ore lens and offsets it 40 m, and the fault zone is full of talc. What kind of structure is it, and what problem does it create?", "opts": ["Pre-mineralisation; it focused the fluid", "Post-mineralisation; it offsets ore and makes bad ground", "Syn-mineralisation; it carries the gold"], "ans": "Post-mineralisation; it offsets ore and makes bad ground", "back": "It cuts and offsets the ore, so it’s younger. Fluid along it grew talc and chlorite: weak ground that’s hard to support and talc that contaminates flotation concentrate."},
 {"id": "L5-cp2", "lecture": 5, "kind": "mc", "front": "Where along a crustal-scale shear zone would you expect orogenic gold deposits?", "opts": ["On the main first-order fault itself", "On second- and third-order splays and cross-faults", "Far from any faults"], "ans": "On second- and third-order splays and cross-faults", "back": "The big fault is the fluid highway, but deposits sit on the smaller off-ramps where fluid slowed, mixed or met reactive rock."},
 {"id": "L5-cp3", "lecture": 5, "kind": "mc", "front": "Which deformation style is critical for Carlin-type gold?", "opts": ["Extension", "Compression", "None: it’s magmatic"], "ans": "Extension", "back": "Extensional faults let fluid rise and spread laterally into reactive silty limestone. Without extension, no deposit."},
 {"id": "L5-cp4", "lecture": 5, "kind": "mc", "front": "What makes an anticline hinge an effective trap for both oil and gold?", "opts": ["It’s the lowest point", "It’s a zone of weakness and the high point beneath an impermeable cap", "It’s always hotter"], "ans": "It’s a zone of weakness and the high point beneath an impermeable cap", "back": "Buoyant fluid rises to the hinge and is held beneath a seal; the hinge also cracks and opens space (saddle reefs)."},
 {"id": "L5-cp5", "lecture": 5, "kind": "mc", "front": "At Granny Smith, gold sits along only one side of a granite. Best explanation?", "opts": ["The granite acted as a rheological barrier to fluid flow", "The granite is the gold source on one side only", "Erosion removed the other side"], "ans": "The granite acted as a rheological barrier to fluid flow", "back": "A rigid granite deflects and ponds fluid along its margin, so local structure controls where the gold sits."},
 {"id": "L5-cp6", "lecture": 5, "kind": "mc", "front": "In the Pilbara, where should you focus gold exploration?", "opts": ["In the centres of granite domes", "In shear zones on the flanks of granite domes, where greenstones sank between them", "Only on the largest regional faults"], "ans": "In shear zones on the flanks of granite domes, where greenstones sank between them", "back": "Dome-and-keel tectonics put the shear zones, and the gold, between the rising domes and the sinking greenstone."},
 {"id": "L5-cp7", "lecture": 5, "kind": "mc", "front": "Which of these is a structure doing the “block flow” job?", "opts": ["A dilational jog opening space", "Fault gouge ground to clay, damming fluid so it drops its load", "A later fault shifting part of the orebody"], "ans": "Fault gouge ground to clay, damming fluid so it drops its load", "back": "Seals make fluid pond and drop its metal: gouge, impermeable beds in fold hinges, dykes."},
 {"id": "L5-cp8", "lecture": 5, "kind": "mc", "front": "Why does later stress usually reactivate bedding planes and old faults instead of breaking fresh rock?", "opts": ["Any existing surface is a plane of weakness", "Old faults are always vertical", "Fresh rock is weaker"], "ans": "Any existing surface is a plane of weakness", "back": "That’s also why contacts weather out first and are hard to find exposed."},
 {"id": "L5-st1", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "Name the four jobs structures do in ore systems.", "back": "Make space for fluid and minerals; block fluid flow so it ponds; soften rock (with fluid, forming chlorite and talc); and offset ore after it forms."},
 {"id": "L5-st2", "lecture": 5, "kind": "q", "lvl": "Think", "front": "Why do pre-existing structures get reactivated rather than new ones forming?", "back": "They’re planes of weakness, so stress partitions into them and they fail at lower stress than intact rock."},
 {"id": "L5-st3", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "Give one example each of pre-, syn- and post-mineralisation structures.", "back": "Pre: bedding, an old growth fault. Syn: a vein, a fault active during porphyry emplacement, slump folds in VMS or SEDEX. Post: a fault that offsets a lode, a shear zone that creates bad ground."},
 {"id": "L5-st4", "lecture": 5, "kind": "q", "lvl": "Think", "front": "Why can VMS deposits only form in extensional ocean settings?", "back": "They need thinned crust over a heat source and permeable faults so seawater can convect, leach metals and vent as black smokers. Extension provides both."},
 {"id": "L5-st5", "lecture": 5, "kind": "q", "lvl": "Apply", "front": "You followed a vein in the hanging wall into a normal fault. Up or down the fault to find it again?", "back": "Up. The hanging wall moved down, so relative to it the footwall continuation is up the fault plane."},
 {"id": "L5-st6", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "How does ore geometry differ between extensional and compressional settings in the same rocks?", "back": "Extension gives open faults that host a large single lens; compression makes folds and faults act as aquitards, so fluid replaces favourable beds beneath them in a series of smaller lenses."},
 {"id": "L5-st7", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "Why do faults often seal oil fields instead of letting them leak?", "back": "Fault movement grinds rock to clay gouge, which is impermeable to oil and gas."},
 {"id": "L5-st8", "lecture": 5, "kind": "q", "lvl": "Think", "front": "Why are the first-order shear zones in the Yilgarn often barren while their splays are rich?", "back": "The large faults are mostly in compression and carry fluid through rather than trapping it; the smaller splays experience extension and dilation, so fluid slows, mixes and precipitates gold there."},
 {"id": "L5-st9", "lecture": 5, "kind": "q", "lvl": "Recall", "front": "What’s characteristic about vein orientation in orogenic gold deposits like Red Lake?", "back": "The orebody plunges steeply to great depth, but individual quartz veins and lenses are close to horizontal."},
 {"id": "L5-st10", "lecture": 5, "kind": "q", "lvl": "Apply", "front": "What are L-tectonites, and why are they found between Pilbara granite domes?", "back": "Rocks dominated by a stretching lineation, like bundles of rods. The dense greenstone keels sank between rising granite domes and were stretched vertically."},
 /* Lecture 6: 33 terms, 11 checkpoints, 10 self-test */
 {"id": "L6-g-anhydrite", "lecture": 6, "kind": "term", "front": "Anhydrite", "back": "Calcium sulphate (CaSO₄). Precipitates when seawater is heated, forming the first walls of chimneys."},
 {"id": "L6-g-back-arc-basin", "lecture": 6, "kind": "term", "front": "Back-arc basin", "back": "A spreading basin behind an arc; hosts about 22% of active vent fields."},
 {"id": "L6-g-black-smoker", "lecture": 6, "kind": "term", "front": "Black smoker", "back": "A high-temperature vent (about 350 to 400 °C) whose fluid precipitates a black cloud of fine metal sulphide particles."},
 {"id": "L6-g-bornite", "lecture": 6, "kind": "term", "front": "Bornite", "back": "A copper-iron sulphide (Cu₅FeS₄); a high-temperature copper mineral in chimney interiors."},
 {"id": "L6-g-brothers-volcano", "lecture": 6, "kind": "term", "front": "Brothers volcano", "back": "A submarine caldera on the Kermadec Arc whose NW caldera hosts a Cu-Au-Ag deposit with up to 90 ppm gold."},
 {"id": "L6-g-caldera", "lecture": 6, "kind": "term", "front": "Caldera", "back": "A large collapse depression at the top of a volcano."},
 {"id": "L6-g-chimney", "lecture": 6, "kind": "term", "front": "Chimney", "back": "A pipe of minerals built around a vent's jet, zoned from hot copper minerals inside to cooler sulphate and zinc minerals outside."},
 {"id": "L6-g-convection", "lecture": 6, "kind": "term", "front": "Convection", "back": "Circulation driven by heat: cold seawater sinks through fractures, heats near the magma and rises to the vents."},
 {"id": "L6-g-ctd", "lecture": 6, "kind": "term", "front": "CTD", "back": "Conductivity-temperature-depth instrument package, towed or lowered from a ship, often with turbidity and ORP sensors."},
 {"id": "L6-g-cubanite", "lecture": 6, "kind": "term", "front": "Cubanite", "back": "A copper-iron sulphide (CuFe₂S₃) found in the hot interior of black smoker chimneys."},
 {"id": "L6-g-diffuse-flow", "lecture": 6, "kind": "term", "front": "Diffuse flow", "back": "Warm fluid (about 2 to 60 °C) seeping out through the seafloor around a vent."},
 {"id": "L6-g-east-pacific-rise", "lecture": 6, "kind": "term", "front": "East Pacific Rise", "back": "The spreading ridge in the eastern Pacific, spreading at about 6 cm a year, where vents were first found in 1977."},
 {"id": "L6-g-entrainment", "lecture": 6, "kind": "term", "front": "Entrainment", "back": "Being swept along by a moving fluid: vapour bubbles are carried up by circulating hydrothermal fluid."},
 {"id": "L6-g-exclusive-economic-zone", "lecture": 6, "kind": "term", "front": "Exclusive economic zone", "back": "The sea area around a nation over which it holds rights to resources, including seafloor minerals."},
 {"id": "L6-g-extremophile", "lecture": 6, "kind": "term", "front": "Extremophile", "back": "An organism that thrives in extreme conditions such as heat, pressure, acidity or salinity."},
 {"id": "L6-g-focused-flow", "lecture": 6, "kind": "term", "front": "Focused flow", "back": "Hot fluid (about 350 °C) channelled up through the vent and chimney."},
 {"id": "L6-g-hyperthermophile", "lecture": 6, "kind": "term", "front": "Hyperthermophile", "back": "An organism that lives above about 80 °C, as at deep-sea vents."},
 {"id": "L6-g-island-arc", "lecture": 6, "kind": "term", "front": "Island arc", "back": "A chain of volcanoes above a subduction zone; the closest modern analogue of most ancient VMS settings."},
 {"id": "L6-g-kermadec-arc", "lecture": 6, "kind": "term", "front": "Kermadec Arc", "back": "An intra-oceanic arc running about 1200 km from New Zealand towards Tonga; the most hydrothermally active in the world."},
 {"id": "L6-g-ligand", "lecture": 6, "kind": "term", "front": "Ligand", "back": "An ion or molecule that bonds to a metal and carries it; here, sulphur in vapour."},
 {"id": "L6-g-metalliferous-sediment", "lecture": 6, "kind": "term", "front": "Metalliferous sediment", "back": "Iron- and manganese-rich sediment that settles out of vent plumes away from the vent; a vector towards sulphides."},
 {"id": "L6-g-mound", "lecture": 6, "kind": "term", "front": "Mound", "back": "A heap of sulphide built up around vents over time, mainly sphalerite, pyrite and some chalcopyrite."},
 {"id": "L6-g-ntu", "lecture": 6, "kind": "term", "front": "NTU", "back": "Nephelometric turbidity units: how much particulate matter scatters light in the water. High NTU marks a plume."},
 {"id": "L6-g-orp", "lecture": 6, "kind": "term", "front": "ORP", "back": "Oxidation-reduction potential: drops sharply where reduced chemicals such as H₂S from fresh vent fluid are present."},
 {"id": "L6-g-palaeoalluvial", "lecture": 6, "kind": "term", "front": "Palaeoalluvial", "back": "An old river (alluvial) deposit now preserved in the rock record, like the Witwatersrand gold."},
 {"id": "L6-g-piezophile", "lecture": 6, "kind": "term", "front": "Piezophile", "back": "An organism that thrives at very high pressure (to 130 MPa), as at deep-sea vents."},
 {"id": "L6-g-pillow-lava", "lecture": 6, "kind": "term", "front": "Pillow lava", "back": "Rounded lava forms made when lava erupts into water; the rims quench to glass."},
 {"id": "L6-g-plume", "lecture": 6, "kind": "term", "front": "Plume", "back": "The cloud of vent fluid and particles that rises from a vent and then spreads sideways and drifts with currents."},
 {"id": "L6-g-sms", "lecture": 6, "kind": "term", "front": "SMS", "back": "Seafloor massive sulphide: the modern, still-forming seafloor equivalent of a VMS deposit."},
 {"id": "L6-g-solwara-1", "lecture": 6, "kind": "term", "front": "Solwara 1", "back": "Seafloor massive sulphide deposit in the Bismarck Sea, PNG: about 7% Cu but only about 2 Mt; never mined."},
 {"id": "L6-g-vapour-exsolution", "lecture": 6, "kind": "term", "front": "Vapour exsolution", "back": "Gas separating out of a magma as bubbles as it rises and decompresses."},
 {"id": "L6-g-vms", "lecture": 6, "kind": "term", "front": "VMS", "back": "Volcanogenic massive sulphide deposit: a body of massive sulphide formed on or just below the seafloor by hydrothermal vents in a volcanic setting."},
 {"id": "L6-g-white-smoker", "lecture": 6, "kind": "term", "front": "White smoker", "back": "A cooler vent (about 260 to 300 °C) giving off pale barium, calcium and silicon minerals such as baryte, anhydrite and silica."},
 {"id": "L6-cp1", "lecture": 6, "kind": "mc", "front": "What can a present-day mineralising system give you that an ancient orebody can’t?", "opts": ["Higher grades", "Direct measurements of fluid temperature, pH, metal content and flow while it forms", "Bigger tonnages"], "ans": "Direct measurements of fluid temperature, pH, metal content and flow while it forms", "back": "A rock is the end result. A living vent lets you quantify the process itself."},
 {"id": "L6-cp2", "lecture": 6, "kind": "mc", "front": "What did the first towed-camera surveys of the East Pacific Rise show?", "opts": ["Every vent is active and the same", "Venting is normal along the ridge, but only some vents are active and they differ in temperature and composition", "Vents occur only at the ends of transform faults"], "ans": "Venting is normal along the ridge, but only some vents are active and they differ in temperature and composition", "back": "Vents switch on and off and vary a lot, which is why ancient deposits record many pulses."},
 {"id": "L6-cp3", "lecture": 6, "kind": "mc", "front": "What mainly makes sulphides precipitate at a black smoker?", "opts": ["Seawater evaporating", "Hot, acidic, metal-rich fluid mixing with cold, alkaline seawater, plus a pressure drop", "Bacteria eating the metals"], "ans": "Hot, acidic, metal-rich fluid mixing with cold, alkaline seawater, plus a pressure drop", "back": "Mixing and the pressure drop at the seafloor make the metals insoluble, so they crystallise as tiny sulphide particles."},
 {"id": "L6-cp4", "lecture": 6, "kind": "mc", "front": "A cut chimney has chalcopyrite and bornite lining its channel and anhydrite on the outside. Why?", "opts": ["The channel carried the hottest fluid, so copper minerals formed there; the outside met cold seawater", "Copper is heavy and sank inwards", "The outside formed later at higher temperature"], "ans": "The channel carried the hottest fluid, so copper minerals formed there; the outside met cold seawater", "back": "Copper minerals need the hottest fluid. Heated seawater on the outer wall precipitates calcium sulphate."},
 {"id": "L6-cp5", "lecture": 6, "kind": "mc", "front": "You find iron-manganese crusts and metalliferous sediment in an old volcanic sequence. What does that suggest?", "opts": ["You’re far from any hydrothermal system", "You’re in the right environment, and sulphide mounds may be nearby", "The rocks were weathered on land"], "ans": "You’re in the right environment, and sulphide mounds may be nearby", "back": "Fe and Mn settle out of plumes away from vents, so they are a vector towards sulphides."},
 {"id": "L6-cp6", "lecture": 6, "kind": "mc", "front": "Tube worms survive at vents because...", "opts": ["they photosynthesise", "they host microbes that use vent chemicals such as sulphide and supply organic compounds", "they eat the chimney"], "ans": "they host microbes that use vent chemicals such as sulphide and supply organic compounds", "back": "It’s a chemical food chain: the microbes turn vent chemistry into organic matter."},
 {"id": "L6-cp7", "lecture": 6, "kind": "mc", "front": "Turbidity is high in a layer above the summit, but ORP drops sharply only over one spot near the seafloor. Where is the vent?", "opts": ["Wherever turbidity is highest in the plume layer", "Under the ORP drop, because dissolved reduced chemicals haven’t spread far", "At the sea surface"], "ans": "Under the ORP drop, because dissolved reduced chemicals haven’t spread far", "back": "Particles in the plume drift with currents. The ORP drop marks fresh vent fluid close to its source."},
 {"id": "L6-cp8", "lecture": 6, "kind": "mc", "front": "About 65% of active vent fields are on mid-ocean ridges, yet ancient VMS deposits look more like arc settings. Why?", "opts": ["Ridge crust is mostly subducted, while arc and back-arc deposits are preserved and tend to be bigger", "Mid-ocean ridges never make sulphides", "Arcs are colder"], "ans": "Ridge crust is mostly subducted, while arc and back-arc deposits are preserved and tend to be bigger", "back": "Preservation decides what reaches the rock record, and arcs also favour larger VMS deposits."},
 {"id": "L6-cp9", "lecture": 6, "kind": "mc", "front": "Why is the Kermadec Arc called a natural laboratory?", "opts": ["It’s the most hydrothermally active intra-oceanic arc, with about 30 major submarine volcanoes and at least three VMS deposits forming now", "It has the deepest trench on Earth", "Its volcanoes are extinct, so it’s safe"], "ans": "It’s the most hydrothermally active intra-oceanic arc, with about 30 major submarine volcanoes and at least three VMS deposits forming now", "back": "You can watch arc-type VMS systems, the best analogues of ancient deposits, in action."},
 {"id": "L6-cp10", "lecture": 6, "kind": "mc", "front": "In the arc vapour-transport model, where do the sulphides finally precipitate?", "opts": ["Deep in the magma chamber", "At the seafloor, where the pressure drops suddenly", "In the atmosphere"], "ans": "At the seafloor, where the pressure drops suddenly", "back": "Vapour carries sulphur and metal up; the sudden pressure drop at the seafloor makes the sulphide insoluble."},
 {"id": "L6-cp11", "lecture": 6, "kind": "mc", "front": "Solwara 1 graded about 7% Cu, ten times a typical land deposit. Why was it never mined?", "opts": ["The grade was too low", "It was tiny (about 2 Mt), couldn’t be drilled to report properly, was costly at 1.6 km depth, and the company went bankrupt", "PNG banned copper mining"], "ans": "It was tiny (about 2 Mt), couldn’t be drilled to report properly, was costly at 1.6 km depth, and the company went bankrupt", "back": "Size and practicality beat grade. Kidd Creek is 115 Mt and Ok Tedi about 910 Mt."},
 {"id": "L6-st1", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "Why are present-day vents so useful for understanding VMS deposits?", "back": "They are a natural laboratory: you can measure fluid temperature, pH, metal content and flux directly, sample chimneys as they form, and compare modern volcanic rocks with ancient terranes to classify old VMS districts."},
 {"id": "L6-st2", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "Write the reaction the slide gives for sphalerite precipitation, and say what drives it.", "back": "Zn²⁺ + 2HS⁻ → ZnS + H₂S. It is driven by hot, acidic, metal-rich vent fluid mixing with cold (2 °C), alkaline, saline seawater, together with the pressure drop at the seafloor."},
 {"id": "L6-st3", "lecture": 6, "kind": "q", "lvl": "Apply", "front": "Describe the mineral zoning across a black smoker chimney wall and explain it.", "back": "Inside, next to the hot channel: chalcopyrite, cubanite and bornite (copper minerals, about 350 °C). Outside, against cold seawater: anhydrite, gypsum and sphalerite. The hot fluid flows up the centre, and heated seawater precipitates calcium sulphate on the outer wall."},
 {"id": "L6-st4", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "How do black and white smokers differ?", "back": "Black smokers are hotter (350 to 400 °C) and precipitate metal sulphides. White smokers are cooler (260 to 300 °C) and give off barium, calcium and silicon minerals such as baryte, anhydrite and amorphous silica."},
 {"id": "L6-st5", "lecture": 6, "kind": "q", "lvl": "Think", "front": "Why are modern vent sulphides finer grained than those in ancient VMS deposits?", "back": "They crystallise instantly as tiny particles when the fluid meets cold seawater. Ancient deposits have had time to be partly recrystallised, which coarsens the grains."},
 {"id": "L6-st6", "lecture": 6, "kind": "q", "lvl": "Think", "front": "What has to happen to a sulphide mound for it to become an ore deposit?", "back": "It must be preserved: buried quickly by lava, ash or sediment, because it is a loose heap of fine sulphide that would otherwise oxidise and break down on the seafloor."},
 {"id": "L6-st7", "lecture": 6, "kind": "q", "lvl": "Apply", "front": "How would you locate an active vent from a ship?", "back": "Map the seafloor with sonar; tow or lower a CTD with a light-scattering sensor to find turbid plumes (high NTU) and an ORP sensor to find fresh reduced fluid; take bottle samples; then sample rock with a submersible or ROV, and possibly drill."},
 {"id": "L6-st8", "lecture": 6, "kind": "q", "lvl": "Recall", "front": "Give the share of active vent fields in each tectonic setting and explain why arcs are the better analogue for ancient VMS.", "back": "About 65% mid-ocean ridge, 22% back-arc, 12% island arc and 1% intraplate. Ridge crust is mostly subducted, while arc and back-arc deposits are preserved, and arcs favour larger sulphide bodies."},
 {"id": "L6-st9", "lecture": 6, "kind": "q", "lvl": "Think", "front": "Explain the vapour-transport model for metals in a magmatic arc system.", "back": "The magma boils and exsolves vapour; sulphur in vapour acts as a ligand and carries metal in compound vapour bubbles; these are entrained by convecting hydrothermal fluid; near the seafloor the pressure drops suddenly, the sulphide becomes insoluble and precipitates at the seafloor."},
 {"id": "L6-st10", "lecture": 6, "kind": "q", "lvl": "Synthesise", "front": "Give four reasons seafloor massive sulphides like Solwara 1 have not been mined.", "back": "Any four: the deposits are tiny (about 2 Mt vs hundreds of Mt on land); tonnage and grade are unpredictable because they rely on grab samples, not drill core, so they can’t be reported normally; it is very expensive at 1.6 km depth in cyclone country; it destroys seafloor life; mining law in international waters is unclear; equipment is hard to repair; and there are enough resources on land."},
 /* Lecture 7: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L7-g-acid", "lecture": 7, "kind": "term", "front": "Acid", "back": "Chemical term: over 63% SiO₂."},
 {"id": "L7-g-compound-flow-facies", "lecture": 7, "kind": "term", "front": "Compound flow facies", "back": "Komatiite fields built of many smaller flow lobes."},
 {"id": "L7-g-contamination", "lecture": 7, "kind": "term", "front": "Contamination", "back": "A magma taking in crustal material (silica, iron-rich rock, carbon) that changes how it crystallises."},
 {"id": "L7-g-cooperite", "lecture": 7, "kind": "term", "front": "Cooperite", "back": "(Pt,Pd,Ni)S, a platinum group mineral."},
 {"id": "L7-g-cumulate", "lecture": 7, "kind": "term", "front": "Cumulate", "back": "A rock or layer made of crystals that accumulated by settling in a magma chamber."},
 {"id": "L7-g-dunite", "lecture": 7, "kind": "term", "front": "Dunite", "back": "Ultramafic rock with over 90% olivine."},
 {"id": "L7-g-epigenetic", "lecture": 7, "kind": "term", "front": "Epigenetic", "back": "Formed after the host rock."},
 {"id": "L7-g-felsic", "lecture": 7, "kind": "term", "front": "Felsic", "back": "Mineralogical term: mostly feldspar and quartz."},
 {"id": "L7-g-flood-flow-facies", "lecture": 7, "kind": "term", "front": "Flood flow facies", "back": "Broad komatiite flow fields from sustained high-volume eruption."},
 {"id": "L7-g-greenstone-belt", "lecture": 7, "kind": "term", "front": "Greenstone belt", "back": "A belt of altered, metamorphosed volcanic rocks, green from serpentine and chlorite."},
 {"id": "L7-g-harzburgite", "lecture": 7, "kind": "term", "front": "Harzburgite", "back": "Ultramafic rock of olivine and orthopyroxene; most of the oceanic mantle."},
 {"id": "L7-g-immiscible", "lecture": 7, "kind": "term", "front": "Immiscible", "back": "Unable to mix: two liquids that stay separate, like oil and water."},
 {"id": "L7-g-interflow-sediment", "lecture": 7, "kind": "term", "front": "Interflow sediment", "back": "Sediment between lava flows; at Kambalda it carried the sulphur."},
 {"id": "L7-g-komatiite", "lecture": 7, "kind": "term", "front": "Komatiite", "back": "An Archaean ultramafic lava, erupted at about 1400 °C with very low viscosity."},
 {"id": "L7-g-laterite", "lecture": 7, "kind": "term", "front": "Laterite", "back": "A deeply weathered, residual soil profile; nickel laterites now supply most of the world’s nickel."},
 {"id": "L7-g-lherzolite", "lecture": 7, "kind": "term", "front": "Lherzolite", "back": "Ultramafic rock of olivine with both orthopyroxene and clinopyroxene; most of the continental mantle."},
 {"id": "L7-g-merensky-reef", "lecture": 7, "kind": "term", "front": "Merensky Reef", "back": "A 1 to 5 m layer in the Bushveld Complex rich in Pt, Fe, Ni, Cu and Cr."},
 {"id": "L7-g-millerite", "lecture": 7, "kind": "term", "front": "Millerite", "back": "NiS, a minor nickel sulphide of the supergene zone."},
 {"id": "L7-g-norite", "lecture": 7, "kind": "term", "front": "Norite", "back": "A gabbro whose pyroxene is orthopyroxene; host to much PGE and sulphide ore."},
 {"id": "L7-g-olivine-suppression", "lecture": 7, "kind": "term", "front": "Olivine suppression", "back": "Stopping olivine crystallising early, so that nickel goes into sulphide melt instead of olivine."},
 {"id": "L7-g-ore-shoot", "lecture": 7, "kind": "term", "front": "Ore shoot", "back": "A ribbon-like, plunging body of ore."},
 {"id": "L7-g-pentlandite", "lecture": 7, "kind": "term", "front": "Pentlandite", "back": "(Fe,Ni)₉S₈, the main nickel ore mineral, in grains and along fractures in pyrrhotite."},
 {"id": "L7-g-peridotite", "lecture": 7, "kind": "term", "front": "Peridotite", "back": "Ultramafic rock of olivine and pyroxene with over 40% olivine."},
 {"id": "L7-g-pyroxenite", "lecture": 7, "kind": "term", "front": "Pyroxenite", "back": "Ultramafic rock with under 40% olivine and more pyroxene than hornblende."},
 {"id": "L7-g-pyrrhotite", "lecture": 7, "kind": "term", "front": "Pyrrhotite", "back": "Fe₁₋ₓS, the bulk of magmatic Ni sulphide ore; oxidises fast and gives off heat."},
 {"id": "L7-g-segregation", "lecture": 7, "kind": "term", "front": "Segregation", "back": "Dense crystals or droplets sinking through a magma and collecting on the chamber floor."},
 {"id": "L7-g-sperrylite", "lecture": 7, "kind": "term", "front": "Sperrylite", "back": "PtAs₂, a platinum arsenide; Norilsk has the best crystals."},
 {"id": "L7-g-spinifex-texture", "lecture": 7, "kind": "term", "front": "Spinifex texture", "back": "Long, thin, bladed olivine crystals in quickly quenched komatiite."},
 {"id": "L7-g-sulphide-melt", "lecture": 7, "kind": "term", "front": "Sulphide melt", "back": "An immiscible sulphide liquid that separates from a mafic or ultramafic silicate magma and collects Ni, Cu and PGE."},
 {"id": "L7-g-syngenetic", "lecture": 7, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host rock."},
 {"id": "L7-g-thermal-erosion", "lecture": 7, "kind": "term", "front": "Thermal erosion", "back": "Hot lava melting and cutting down into the rock it flows over."},
 {"id": "L7-g-ultrabasic", "lecture": 7, "kind": "term", "front": "Ultrabasic", "back": "Chemical term: under 45% SiO₂."},
 {"id": "L7-cp1", "lecture": 7, "kind": "mc", "front": "What do all magmatic ore deposits have in common?", "opts": ["They formed from seawater", "They are associated with primary, mantle-derived magmas", "They are all in granites"], "ans": "They are associated with primary, mantle-derived magmas", "back": "Ni-Cu sulphides, PGE, Cr-V-Ti oxides, P, REE and diamonds all come from mantle-derived magmas."},
 {"id": "L7-cp2", "lecture": 7, "kind": "mc", "front": "A rock is 70% olivine and 30% orthopyroxene, with no clinopyroxene. What is it?", "opts": ["Dunite", "Harzburgite", "Wehrlite"], "ans": "Harzburgite", "back": "Olivine plus orthopyroxene is harzburgite, the main rock of the oceanic mantle. Dunite needs over 90% olivine."},
 {"id": "L7-cp3", "lecture": 7, "kind": "mc", "front": "Why does a magma need olivine suppressed to make a nickel sulphide deposit?", "opts": ["Olivine is too dense", "Early olivine takes the nickel into its structure, leaving none for the sulphide melt", "Olivine dissolves sulphide"], "ans": "Early olivine takes the nickel into its structure, leaving none for the sulphide melt", "back": "Suppress olivine (with silica, iron or reducing contamination) and nickel goes into the immiscible sulphide liquid."},
 {"id": "L7-cp4", "lecture": 7, "kind": "mc", "front": "Why does plagioclase tend to float to the top of a mafic magma chamber?", "opts": ["It has about the same density as mafic magma (2.8), slightly less", "It is magnetic", "It crystallises last"], "ans": "It has about the same density as mafic magma (2.8), slightly less", "back": "Minerals denser than the 2.8 magma sink; plagioclase, at about 2.8, rises to the top instead."},
 {"id": "L7-cp5", "lecture": 7, "kind": "mc", "front": "Which deposit is both very large and high grade, with nearly 4% Cu and about 10 g/t PGE?", "opts": ["Duluth", "Norilsk", "Mount Keith"], "ans": "Norilsk", "back": "Norilsk: 1257 Mt at 1.84% Ni, 3.75% Cu, 10 g/t PGE. Duluth is huge but very low grade."},
 {"id": "L7-cp6", "lecture": 7, "kind": "mc", "front": "Where does most of the world’s nickel come from now?", "opts": ["Primary sulphide deposits like Kambalda", "Laterites, mainly in Indonesia, the Philippines and New Caledonia", "Seafloor nodules"], "ans": "Laterites, mainly in Indonesia, the Philippines and New Caledonia", "back": "New processing made laterites cheap; they now supply around 65%, and Indonesia leads."},
 {"id": "L7-cp7", "lecture": 7, "kind": "mc", "front": "Most of the sulphide in Kambalda ore is pyrrhotite, yet the miners want...", "opts": ["pyrite", "pentlandite, the main nickel mineral", "magnetite"], "ans": "pentlandite, the main nickel mineral", "back": "Pentlandite carries the nickel, as grains and along fractures in the pyrrhotite."},
 {"id": "L7-cp8", "lecture": 7, "kind": "mc", "front": "Where did the sulphur in the komatiite-hosted deposits come from?", "opts": ["The mantle only", "Sulphide-bearing sediments between the lava flows", "Seawater sulphate in the vents"], "ans": "Sulphide-bearing sediments between the lava flows", "back": "The hot lava eroded and assimilated the interflow sulphidic sediments."},
 {"id": "L7-cp9", "lecture": 7, "kind": "mc", "front": "In a komatiite lava river, where do you get massive sulphide rather than disseminated?", "opts": ["Where the flow is fast and turbulent", "Where the flow is quiet, so sulphide droplets have time to sink to the base", "Only at the flow top"], "ans": "Where the flow is quiet, so sulphide droplets have time to sink to the base", "back": "Quiescent flow lets the sulphide segregate to the base; high velocity keeps it mixed and disseminated."},
 {"id": "L7-cp10", "lecture": 7, "kind": "mc", "front": "Why is drilling so critical at Kambalda?", "opts": ["The ore is very deep", "The ribbon-like shoots are narrow and have been cut and offset by faults, folds and dykes", "Gold gets in the way"], "ans": "The ribbon-like shoots are narrow and have been cut and offset by faults, folds and dykes", "back": "Long, narrow lenses that later deformation has moved are easy to miss."},
 {"id": "L7-cp11", "lecture": 7, "kind": "mc", "front": "Mount Keith grades only about 0.6% Ni. Why can it be mined?", "opts": ["It is very high in gold", "It is about a billion tonnes and could be open cut from the surface", "It is under a salt lake"], "ans": "It is about a billion tonnes and could be open cut from the surface", "back": "Size and easy access make up for the low grade."},
 {"id": "L7-st1", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "Distinguish acid from felsic, and basic from mafic.", "back": "Acid and basic are chemical terms based on silica (over 63%; 45 to 55%). Felsic and mafic are mineralogical terms (mostly feldspar and quartz; mostly dark minerals plus plagioclase)."},
 {"id": "L7-st2", "lecture": 7, "kind": "q", "lvl": "Apply", "front": "Explain olivine suppression and give three ways a magma can achieve it.", "back": "Olivine crystallising early takes nickel into its structure. If olivine is suppressed, pyroxene crystallises first and nickel goes into the immiscible sulphide melt. Silica contamination (olivine + SiO₂ → pyroxene), contamination by iron-rich rock, or a reducing environment such as a coal bed."},
 {"id": "L7-st3", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "Why do chromite, magnetite and sulphide droplets collect at the base of a magma chamber while plagioclase does not?", "back": "They are much denser (chromite 4.5 to 4.8, magnetite 5.1, chalcopyrite 4.2) than mafic magma (2.8), so they sink and form cumulates. Plagioclase (2.8) has about the same density and floats to the top."},
 {"id": "L7-st4", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "Describe the general relationship between grade and tonnage in magmatic Ni-Cu deposits, with an exception.", "back": "High-grade deposits tend to be small (Victor and Cosmos, over 10% Ni, about 1 Mt) and the largest tend to be low grade (Duluth, 4000 Mt at 0.2%). Norilsk is the exception: 1257 Mt at 1.84% Ni, 3.75% Cu and 10 g/t PGE."},
 {"id": "L7-st5", "lecture": 7, "kind": "q", "lvl": "Think", "front": "Why has Australian nickel production collapsed in recent years?", "back": "Laterites, mainly in Indonesia, became cheap to process, helped by Chinese investment in central processing plants on Sulawesi. Australian sulphide mines can’t compete on cost, so production fell from 160 000 t (2023) to 45 000 t (2025) and much of Kambalda is on hold."},
 {"id": "L7-st6", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "List the main ore minerals of a magmatic Ni-Cu sulphide deposit and the role of each.", "back": "Pyrrhotite (the bulk; oxidises fast and gives off heat), pentlandite (main Ni mineral), chalcopyrite (main Cu mineral), with minor millerite (supergene NiS), cooperite and sperrylite (PGE minerals) and magnetite."},
 {"id": "L7-st7", "lecture": 7, "kind": "q", "lvl": "Think", "front": "Why are komatiites restricted to the Archaean, and what textures do they show?", "back": "The mantle was much hotter, so ultramafic melts erupted at about 1400 °C. Slowly cooled channels show cumulate textures; thin, fast-quenched sheet flows show spinifex texture."},
 {"id": "L7-st8", "lecture": 7, "kind": "q", "lvl": "Recall", "front": "How did Western Mining find Kambalda when Canadian explorers didn’t?", "back": "The Canadians explored as if for fresh, glaciated outcrop. Kambalda has about 100 m of weathered cover; Western Mining understood weathered terrain and found the nickel with soil geochemistry."},
 {"id": "L7-st9", "lecture": 7, "kind": "q", "lvl": "Apply", "front": "Explain how flow velocity controls massive versus disseminated sulphide in a komatiite channel.", "back": "Thermal erosion of sulphidic sediment releases sulphur that forms sulphide droplets. Where the flow is quiet, droplets have time to sink and pool at the base as massive sulphide; where it is fast and turbulent, they stay mixed through the lava as disseminated sulphide."},
 {"id": "L7-st10", "lecture": 7, "kind": "q", "lvl": "Synthesise", "front": "Compare Type 1 (Kambalda) and Type 2 (Mount Keith) komatiite-hosted deposits.", "back": "Type 1: thin ribbons (1 to 5 m thick, 50 to 100 m wide, 100 to 700 m long, under 5 Mt), stratified massive-matrix-disseminated sulphide with up to 20% Ni at the base, in lava channels with thermal erosion. Type 2: a thick cumulate body (up to 800 m thick, 1 to 3 km wide) with 1 to 5% disseminated sulphide in olivine cumulate, about 0.6% Ni but very large (about 1 billion t) and open-pittable."},
 /* Lecture 8: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L8-g-alkaline-intrusion", "lecture": 8, "kind": "term", "front": "Alkaline intrusion", "back": "An intrusion rich in Na and K, often with exotic minerals, REE and apatite."},
 {"id": "L8-g-anorthosite", "lecture": 8, "kind": "term", "front": "Anorthosite", "back": "A rock made almost entirely of plagioclase; it forms where plagioclase floats in a magma chamber."},
 {"id": "L8-g-apatite", "lecture": 8, "kind": "term", "front": "Apatite", "back": "A calcium phosphate mineral; the ore of phosphorus."},
 {"id": "L8-g-chromitite", "lecture": 8, "kind": "term", "front": "Chromitite", "back": "A rock made mostly of chromite."},
 {"id": "L8-g-contamination", "lecture": 8, "kind": "term", "front": "Contamination", "back": "Crustal material (silica, sulphur, Fe³⁺, carbon, sulphate) added to a magma, triggering early sulphide saturation."},
 {"id": "L8-g-evaporite", "lecture": 8, "kind": "term", "front": "Evaporite", "back": "Salt and sulphate rock left by evaporation; at Norilsk it supplied sulphur."},
 {"id": "L8-g-flood-basalt", "lecture": 8, "kind": "term", "front": "Flood basalt", "back": "An enormous outpouring of basalt lava, like the Permian-Triassic Siberian Traps at Norilsk."},
 {"id": "L8-g-garnierite", "lecture": 8, "kind": "term", "front": "Garnierite", "back": "A talc-like Ni-Mg silicate of high-grade laterite ore."},
 {"id": "L8-g-granophyre", "lecture": 8, "kind": "term", "front": "Granophyre", "back": "A fine-grained granitic rock; the upper part of the Sudbury melt sheet."},
 {"id": "L8-g-hortonolite", "lecture": 8, "kind": "term", "front": "Hortonolite", "back": "An iron-rich olivine; hortonolite pipes in the Bushveld were the first hard-rock platinum mined."},
 {"id": "L8-g-ipge", "lecture": 8, "kind": "term", "front": "IPGE", "back": "Iridium, osmium and ruthenium: they tend to stay in the host rock."},
 {"id": "L8-g-layered-intrusion", "lecture": 8, "kind": "term", "front": "Layered intrusion", "back": "A large mafic-ultramafic intrusion built of layers of settled crystals, like the Bushveld."},
 {"id": "L8-g-limonite-zone", "lecture": 8, "kind": "term", "front": "Limonite zone", "back": "Fine goethite-rich zone of a laterite; highest cobalt."},
 {"id": "L8-g-merensky-reef", "lecture": 8, "kind": "term", "front": "Merensky Reef", "back": "A thin, pegmatoidal Bushveld layer rich in PGE, Ni, Cu and Cr."},
 {"id": "L8-g-nickel-laterite", "lecture": 8, "kind": "term", "front": "Nickel laterite", "back": "A nickel deposit formed by intense weathering of ultramafic rock."},
 {"id": "L8-g-nodular-chromitite", "lecture": 8, "kind": "term", "front": "Nodular chromitite", "back": "Chromitite made of rounded chromite nodules, typical of podiform deposits."},
 {"id": "L8-g-offset-dyke", "lecture": 8, "kind": "term", "front": "Offset dyke", "back": "A radial or concentric dyke of quartz diorite around the Sudbury structure; many host ore."},
 {"id": "L8-g-ophiolite", "lecture": 8, "kind": "term", "front": "Ophiolite", "back": "A slice of oceanic lithosphere (mantle and crust) thrust onto land."},
 {"id": "L8-g-pal", "lecture": 8, "kind": "term", "front": "PAL", "back": "Pressure acid leaching: processing clay-type laterite with acid at high pressure."},
 {"id": "L8-g-partition-coefficient", "lecture": 8, "kind": "term", "front": "Partition coefficient", "back": "How strongly an element prefers one phase over another, here sulphide over silicate melt."},
 {"id": "L8-g-platreef", "lecture": 8, "kind": "term", "front": "Platreef", "back": "The PGE-bearing pyroxenite of the Bushveld’s northern limb, with interstitial sulphide."},
 {"id": "L8-g-podiform-chromitite", "lecture": 8, "kind": "term", "front": "Podiform chromitite", "back": "A pod of chromitite in the mantle part of an ophiolite, source of metallurgical-grade chromium."},
 {"id": "L8-g-pothole", "lecture": 8, "kind": "term", "front": "Pothole", "back": "A dip in a Bushveld reef where a hot new magma batch thermally eroded the layer below."},
 {"id": "L8-g-ppge", "lecture": 8, "kind": "term", "front": "PPGE", "back": "Platinum, palladium and rhodium: they partition into sulphide."},
 {"id": "L8-g-r-factor", "lecture": 8, "kind": "term", "front": "R-factor", "back": "The mass ratio of silicate magma to the sulphide melt it has equilibrated with. High R: a little sulphide, very rich in Ni, Cu and PGE."},
 {"id": "L8-g-saprolite", "lecture": 8, "kind": "term", "front": "Saprolite", "back": "Weathered rock that keeps the parent texture; the highest-Ni zone of a laterite."},
 {"id": "L8-g-shatter-cone", "lecture": 8, "kind": "term", "front": "Shatter cone", "back": "A striated, cone-shaped fracture formed by the shock wave of a meteorite impact."},
 {"id": "L8-g-sublayer", "lecture": 8, "kind": "term", "front": "Sublayer", "back": "The inclusion-rich, contaminated base of the Sudbury Igneous Complex, rich in sulphide."},
 {"id": "L8-g-sulphide-saturation", "lecture": 8, "kind": "term", "front": "Sulphide saturation", "back": "The point at which a silicate magma can hold no more sulphur, so immiscible sulphide droplets form."},
 {"id": "L8-g-taxitic", "lecture": 8, "kind": "term", "front": "Taxitic", "back": "An irregular, mish-mash texture with no particular pattern, typical of Norilsk ore-bearing gabbro-dolerite."},
 {"id": "L8-g-ug2", "lecture": 8, "kind": "term", "front": "UG2", "back": "The Bushveld’s Upper Group 2 chromitite: the world’s largest platinum resource."},
 {"id": "L8-g-violarite", "lecture": 8, "kind": "term", "front": "Violarite", "back": "Ni₂FeS₄, which replaces pyrrhotite and pentlandite during deep oxidation."},
 {"id": "L8-cp1", "lecture": 8, "kind": "mc", "front": "For a magmatic nickel sulphide deposit you want...", "opts": ["a small R-factor: lots of sulphide melt", "a large R-factor: a little sulphide melt that has met a lot of magma", "no sulphide at all"], "ans": "a large R-factor: a little sulphide melt that has met a lot of magma", "back": "A high R-factor concentrates Ni, Cu and PGE into a small volume of sulphide. Laterites want the opposite."},
 {"id": "L8-cp2", "lecture": 8, "kind": "mc", "front": "In an intrusion-hosted deposit, where is the massive sulphide?", "opts": ["At the top of the intrusion", "In the lower zone, at the base and contact, overlain by network then disseminated sulphide", "Only in the country rock far away"], "ans": "In the lower zone, at the base and contact, overlain by network then disseminated sulphide", "back": "Dense sulphide liquid collects at the base: massive (over 70%), then network, then disseminated."},
 {"id": "L8-cp3", "lecture": 8, "kind": "mc", "front": "Why is Sudbury unique among Ni-Cu deposits?", "opts": ["It formed in a meteorite impact structure, with mantle melt rising through impact fractures", "It is a laterite", "It has no sulphide"], "ans": "It formed in a meteorite impact structure, with mantle melt rising through impact fractures", "back": "An impact into a rifting region fractured the crust down to the mantle; ore sits in the sublayer and offset dykes."},
 {"id": "L8-cp4", "lecture": 8, "kind": "mc", "front": "At Norilsk, what supplied much of the sulphur?", "opts": ["Seawater", "Evaporites intruded by the sills", "The mantle alone"], "ans": "Evaporites intruded by the sills", "back": "The sills intruded evaporites, whose sulphate added sulphur, along with silica and Fe³⁺ from the country rocks."},
 {"id": "L8-cp5", "lecture": 8, "kind": "mc", "front": "Why do massive sulphides collect at the base of an intrusion or flow?", "opts": ["Sulphide liquid (about 4.4) is far denser than silicate liquid (about 3.3)", "They crystallise first at the top and fall", "Groundwater carries them down"], "ans": "Sulphide liquid (about 4.4) is far denser than silicate liquid (about 3.3)", "back": "Gravity segregation, helped by flow separation."},
 {"id": "L8-cp6", "lecture": 8, "kind": "mc", "front": "Which deposit is small but has by far the highest PGE grade on slide 24?", "opts": ["UG2", "Stillwater, about 21 g/t", "Platreef"], "ans": "Stillwater, about 21 g/t", "back": "Stillwater: 323 Mt at 20.7 g/t PGE. UG2 is the giant, 5743 Mt at 5.7 g/t."},
 {"id": "L8-cp7", "lecture": 8, "kind": "mc", "front": "What makes the alternating chromitite and anorthosite layers in the Bushveld?", "opts": ["Each new magma batch settles dense chromite at the base while plagioclase floats", "Hydrothermal veins", "Weathering"], "ans": "Each new magma batch settles dense chromite at the base while plagioclase floats", "back": "Repeated batches give rhythmic layering; a hot batch can also erode a pothole."},
 {"id": "L8-cp8", "lecture": 8, "kind": "mc", "front": "Where does metallurgical-grade chromium come from?", "opts": ["Podiform chromitites in the mantle part of ophiolites", "Laterites", "Mineral sands"], "ans": "Podiform chromitites in the mantle part of ophiolites", "back": "Layered intrusions like the Bushveld give chemical-grade chromium; podiform pods give metallurgical grade."},
 {"id": "L8-cp9", "lecture": 8, "kind": "mc", "front": "A chromitite pod sits in a dunite envelope inside harzburgite. Why the dunite?", "opts": ["It is a reaction rim where the basaltic magma in the channel reacted with harzburgite", "It is weathered chromite", "It came from a later dyke"], "ans": "It is a reaction rim where the basaltic magma in the channel reacted with harzburgite", "back": "Podiform chromitites are conduits; the magma reacts with the host and leaves dunite around the channel."},
 {"id": "L8-cp10", "lecture": 8, "kind": "mc", "front": "What is the ore mineral of primary magmatic phosphorus deposits?", "opts": ["Apatite", "Monazite", "Chromite"], "ans": "Apatite", "back": "Apatite, in lenses within layered intrusions or alkaline syenites like Khibiny."},
 {"id": "L8-cp11", "lecture": 8, "kind": "mc", "front": "Which laterite zone has the highest nickel?", "opts": ["Ferricrete at the top", "Saprolite, where the parent rock texture is preserved", "Fresh peridotite at the base"], "ans": "Saprolite, where the parent rock texture is preserved", "back": "Saprolite has the highest Ni; the limonite zone above has the highest Co."},
 {"id": "L8-st1", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "Define the R-factor and say why nickel sulphide and nickel laterite deposits want opposite values.", "back": "The ratio of silicate magma to the sulphide melt it equilibrates with. Sulphide deposits want a high R (a small volume of sulphide very rich in Ni, Cu, PGE); laterites want a low R so nickel stays in olivine, to be concentrated later by weathering."},
 {"id": "L8-st2", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "Describe the zoning and mineralogy of an intrusion-hosted Ni-Cu deposit.", "back": "A lower zone of massive and brecciated sulphide (over 70%), then network (40 to 70%) and disseminated (15 to 40%) sulphide. About 70% pyrrhotite, 15% pentlandite, 15% chalcopyrite."},
 {"id": "L8-st3", "lecture": 8, "kind": "q", "lvl": "Apply", "front": "Why does contamination matter so much in these deposits? Give three contaminants.", "back": "It triggers early sulphide saturation (and olivine suppression). Silica-rich crust, crustal sulphur (sulphide-bearing sediments or evaporite sulphate), Fe³⁺, and carbon such as coal."},
 {"id": "L8-st4", "lecture": 8, "kind": "q", "lvl": "Think", "front": "Outline the Sudbury model from impact to ore.", "back": "An impact into a rifting region fractured the crust down to the mantle. A melt sheet formed and quartz diorite was injected into offset dykes. The sheet separated into norite below and granophyre above; dense sulphides segregated into the sublayer embayments and offsets; Cu-rich fractions moved furthest out, as at Copper Cliff."},
 {"id": "L8-st5", "lecture": 8, "kind": "q", "lvl": "Think", "front": "Why can Norilsk be mined to great depth while Voisey’s Bay exposes a deep chamber?", "back": "Norilsk’s whole plumbing system, from sills to the lavas above, is preserved. At Voisey’s Bay erosion has stripped the upper levels, exposing the mid-crustal chamber level."},
 {"id": "L8-st6", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "Distinguish PPGE from IPGE.", "back": "PPGE (Pt, Pd, Rh) partition strongly into sulphide; IPGE (Ir, Os, Ru) tend to stay in the host rock."},
 {"id": "L8-st7", "lecture": 8, "kind": "q", "lvl": "Apply", "front": "Explain rhythmic chromitite-anorthosite layering and potholes in the Bushveld.", "back": "Each new batch of magma crystallises dense chromite that sinks to form chromitite and plagioclase that floats to form anorthosite. A hotter new batch can thermally erode the layer below, making potholes in the Merensky Reef."},
 {"id": "L8-st8", "lecture": 8, "kind": "q", "lvl": "Recall", "front": "List the conditions needed to form an economic Cr-V-Ti oxide deposit.", "back": "High initial Cr, Ti, V or replenishment; early crystallisation of chromite, magnetite, ilmenite; a concentrating process (gravity, segregation, movement); stable T, P and oxidation state for thick layers; removal of light minerals such as floating plagioclase; preservation."},
 {"id": "L8-st9", "lecture": 8, "kind": "q", "lvl": "Think", "front": "How do podiform chromitites form, and why are they found only in ophiolites?", "back": "Basaltic magma flows through channels in mantle harzburgite, reacts with it to leave a dunite rim, and crystallises chromite by magma mixing; the dense chromite accumulates as pods. This happens in the oceanic upper mantle, which is only exposed on land in ophiolites."},
 {"id": "L8-st10", "lecture": 8, "kind": "q", "lvl": "Synthesise", "front": "Draw or describe a nickel laterite profile and say where Ni and Co peak and how each ore type is processed.", "back": "From the top: ferricrete, transported limonite, limonite (highest Co, Ni highest at its base), intermediate zone of quartz and kaolinite, saprolite (highest Ni), fresh peridotite. Garnierite ore is smelted, clay ore is processed by pressure acid leaching, limonitic ore by ammonia leach."},
 /* Lecture 9: 34 terms, 11 checkpoints, 10 self-test */
 {"id": "L9-g-ankerite", "lecture": 9, "kind": "term", "front": "Ankerite", "back": "Ca(Fe,Mg)(CO₃)₂, an iron-bearing carbonate; pale orange to yellow, part of the halo around SEDEX ore."},
 {"id": "L9-g-anoxic", "lecture": 9, "kind": "term", "front": "Anoxic", "back": "Without oxygen; an anoxic basin floor holds H₂S and preserves organic matter."},
 {"id": "L9-g-aquifer", "lecture": 9, "kind": "term", "front": "Aquifer", "back": "A permeable rock layer that holds and transmits fluid; in SEDEX, the coarse syn-rift clastics."},
 {"id": "L9-g-aquitard", "lecture": 9, "kind": "term", "front": "Aquitard", "back": "An impermeable layer that holds fluid in, here post-rift shale, chert or carbonate."},
 {"id": "L9-g-back-arc", "lecture": 9, "kind": "term", "front": "Back-arc", "back": "The region behind a volcanic arc, on the side away from the trench, often under extension."},
 {"id": "L9-g-barite", "lecture": 9, "kind": "term", "front": "Barite", "back": "BaSO₄, a common, dense gangue mineral in SEDEX deposits, more abundant away from the vent."},
 {"id": "L9-g-barney-creek-formation", "lecture": 9, "kind": "term", "front": "Barney Creek Formation", "back": "The organic-rich dolomitic siltstone of the McArthur Group that hosts HYC."},
 {"id": "L9-g-brine-pool", "lecture": 9, "kind": "term", "front": "Brine pool", "back": "A body of dense, salty fluid lying in a depression on the seafloor."},
 {"id": "L9-g-chalcopyrite-disease", "lecture": 9, "kind": "term", "front": "Chalcopyrite disease", "back": "Tiny chalcopyrite inclusions in sphalerite, used as a sign of higher formation temperature."},
 {"id": "L9-g-chloride-complex", "lecture": 9, "kind": "term", "front": "Chloride complex", "back": "A dissolved metal bonded to chloride, like ZnCl₂, the way zinc and lead travel in saline brine."},
 {"id": "L9-g-diagenetic", "lecture": 9, "kind": "term", "front": "Diagenetic", "back": "Formed in the sediment soon after burial, while it is still being compacted and cemented."},
 {"id": "L9-g-epigenetic", "lecture": 9, "kind": "term", "front": "Epigenetic", "back": "Formed after the host rock, for example by later replacement or veining."},
 {"id": "L9-g-exhalative", "lecture": 9, "kind": "term", "front": "Exhalative", "back": "Deposited from fluid vented (exhaled) onto the seafloor."},
 {"id": "L9-g-ferroan-dolomite", "lecture": 9, "kind": "term", "front": "Ferroan dolomite", "back": "Dolomite with some iron, between ankerite and plain dolomite in the halo sequence."},
 {"id": "L9-g-galena", "lecture": 9, "kind": "term", "front": "Galena", "back": "PbS, the main lead ore mineral; white with triangular cleavage pits in reflected light; very dense."},
 {"id": "L9-g-galvanising", "lecture": 9, "kind": "term", "front": "Galvanising", "back": "Coating steel with zinc to stop it rusting; about 60% of zinc use."},
 {"id": "L9-g-growth-fault", "lecture": 9, "kind": "term", "front": "Growth fault", "back": "A normal fault that moves while sediment is deposited, so beds thicken across it."},
 {"id": "L9-g-hematite-pyrite-buffer", "lecture": 9, "kind": "term", "front": "Hematite-pyrite buffer", "back": "The redox boundary where hematite gives way to pyrite; above it, brines can carry far more Zn and Pb."},
 {"id": "L9-g-hemimorphite", "lecture": 9, "kind": "term", "front": "Hemimorphite", "back": "Zn₄Si₂O₇(OH)₂·H₂O, a white zinc silicate formed by weathering of zinc sulphide."},
 {"id": "L9-g-irish-type", "lecture": 9, "kind": "term", "front": "Irish-type", "back": "Zn-Pb deposits in Carboniferous carbonates in Ireland, sharing features with both SEDEX and MVT."},
 {"id": "L9-g-mvt", "lecture": 9, "kind": "term", "front": "MVT", "back": "Mississippi Valley-type: Zn-Pb deposits that replace carbonate rocks, from basin brines, with no exhalation onto the seafloor."},
 {"id": "L9-g-overpressured", "lecture": 9, "kind": "term", "front": "Overpressured", "back": "Holding fluid at more than the normal hydrostatic pressure for its depth; also called geopressured."},
 {"id": "L9-g-sedex", "lecture": 9, "kind": "term", "front": "SEDEX", "back": "Sedimentary exhalative: a Zn-Pb-Ag deposit formed where basin brine vents into a reduced sedimentary basin; also called sediment-hosted massive sulphide (SHMS)."},
 {"id": "L9-g-siderite", "lecture": 9, "kind": "term", "front": "Siderite", "back": "FeCO₃, iron carbonate; brown spots closest to the ore in north Australian halos."},
 {"id": "L9-g-sphalerite", "lecture": 9, "kind": "term", "front": "Sphalerite", "back": "ZnS, the main zinc ore mineral; grey with low reflectance in reflected light."},
 {"id": "L9-g-syn-rift", "lecture": 9, "kind": "term", "front": "Syn-rift", "back": "Deposited while the rift was actively extending; here coarse, permeable clastics."},
 {"id": "L9-g-syngenetic", "lecture": 9, "kind": "term", "front": "Syngenetic", "back": "Formed at the same time as the host rock, here sulphide laid down with the sediment."},
 {"id": "L9-g-thallium-halo", "lecture": 9, "kind": "term", "front": "Thallium halo", "back": "A subtle enrichment of thallium (a few ppm) in the host rocks around SEDEX ore, found by assay."},
 {"id": "L9-g-tourmaline", "lecture": 9, "kind": "term", "front": "Tourmaline", "back": "A boron silicate; common near SEDEX vents because seawater supplies boron."},
 {"id": "L9-g-turbidite", "lecture": 9, "kind": "term", "front": "Turbidite", "back": "A graded bed laid down by a turbidity current or mass flow sliding off a slope."},
 {"id": "L9-g-vent-distal", "lecture": 9, "kind": "term", "front": "Vent-distal", "back": "Formed away from the vent from dense brine pooled in depressions: laminated sulphide, barite, no footwall alteration."},
 {"id": "L9-g-vent-proximal", "lecture": 9, "kind": "term", "front": "Vent-proximal", "back": "Formed at or near the vent from buoyant fluid: footwall alteration, breccia pipes, coarser sulphide."},
 {"id": "L9-g-vms", "lecture": 9, "kind": "term", "front": "VMS", "back": "Volcanogenic (volcanic-hosted) massive sulphide: a Cu-Zn-Pb deposit formed by seafloor venting in a volcanic setting (Lecture 10)."},
 {"id": "L9-g-value", "lecture": 9, "kind": "term", "front": "Μ value", "back": "The ²³⁸U/²⁰⁴Pb ratio of a lead source; high μ points to upper continental crust."},
 {"id": "L9-cp1", "lecture": 9, "kind": "mc", "front": "What does most SEDEX ore look like?", "opts": ["Massive chalcopyrite lenses", "Fine laminae of sphalerite and galena interbedded with shale or siltstone", "Coarse gold in quartz veins"], "ans": "Fine laminae of sphalerite and galena interbedded with shale or siltstone", "back": "The sulphides sit in thin laminae between shale and siltstone layers, often so fine that they are hard to process, as at HYC."},
 {"id": "L9-cp2", "lecture": 9, "kind": "mc", "front": "How does Australia rank for zinc?", "opts": ["Third-largest producer, but the largest reserves", "Largest producer, with small reserves", "A minor producer with no reserves"], "ans": "Third-largest producer, but the largest reserves", "back": "About 1100 kt a year, behind China and Peru, but 64 000 kt of reserves, ahead of China. For lead it is second producer and first in reserves."},
 {"id": "L9-cp3", "lecture": 9, "kind": "mc", "front": "Why does a SEDEX basin need an impermeable cap above the aquifer?", "opts": ["To make the fluid hotter", "To supply sulphur", "To hold the brine in so it builds pressure and then discharges in a focused way"], "ans": "To hold the brine in so it builds pressure and then discharges in a focused way", "back": "Without the aquitard, brine leaks away up the faults and you get elevated background metal, not a deposit."},
 {"id": "L9-cp4", "lecture": 9, "kind": "mc", "front": "Which unit hosts HYC in the McArthur Basin?", "opts": ["Tawallah Group rift volcanics", "Barney Creek Formation organic-rich dolomitic siltstone, in the sag phase", "The platform carbonates at the top"], "ans": "Barney Creek Formation organic-rich dolomitic siltstone, in the sag phase", "back": "Rift-phase Tawallah Group below is the aquifer; the sag-phase Barney Creek Formation hosts HYC; platform carbonates on top sealed it."},
 {"id": "L9-cp5", "lecture": 9, "kind": "mc", "front": "Why does brine leave the aquifer in pulses?", "opts": ["Overpressure builds until the cap ruptures and the fault opens, often in a small earthquake, then the fault seals again", "Tides pump it out twice a day", "Rain pushes it down and out"], "ans": "Overpressure builds until the cap ruptures and the fault opens, often in a small earthquake, then the fault seals again", "back": "Each rupture releases a pulse; mineral precipitation reseals the fault, and pressure builds again."},
 {"id": "L9-cp6", "lecture": 9, "kind": "mc", "front": "A brine denser than seawater flows out of a vent. What do you get?", "opts": ["A buoyant plume and a mound over the vent", "No deposit at all", "A brine pool in a depression, laying down laminated sulphide with no footwall alteration"], "ans": "A brine pool in a depression, laying down laminated sulphide with no footwall alteration", "back": "That is the vent-distal style, like HYC: more saline, cooler, oxidised brine."},
 {"id": "L9-cp7", "lecture": 9, "kind": "mc", "front": "Where do the zinc and the sulphur mostly come from?", "opts": ["Zinc from the basin sediments, leached by brine; sulphur from H₂S in the anoxic seawater", "Both from a granite", "Both from the mantle"], "ans": "Zinc from the basin sediments, leached by brine; sulphur from H₂S in the anoxic seawater", "back": "Metals from the basin fill, mobilised by convecting brine; sulphur from the water column."},
 {"id": "L9-cp8", "lecture": 9, "kind": "mc", "front": "In a stratified SEDEX basin, where does sphalerite precipitate?", "opts": ["In the oxygenated surface water", "In the aquifer, deep in the basin", "Where metal-bearing brine meets H₂S in the anoxic bottom water"], "ans": "Where metal-bearing brine meets H₂S in the anoxic bottom water", "back": "Chloride-complexed zinc meets H₂S, ZnS precipitates, and aggregates sink to the floor."},
 {"id": "L9-cp9", "lecture": 9, "kind": "mc", "front": "Walking away from the vent along the ore horizon, what changes?", "opts": ["Grade rises and Pb:Zn rises", "Grade, Pb:Zn and thickness decrease; Ba:Zn increases", "Copper increases"], "ans": "Grade, Pb:Zn and thickness decrease; Ba:Zn increases", "back": "Distal ore is thinner, lower grade, more zinc-rich and more barite-rich, grading into chert and barite."},
 {"id": "L9-cp10", "lecture": 9, "kind": "mc", "front": "Drilling through dolomitic host rock toward a north Australian SEDEX ore body, which carbonates do you log as you get closer?", "opts": ["Siderite → ankerite → ferroan dolomite → dolomite", "Dolomite → ferroan dolomite → ankerite → siderite", "Calcite only, all the way"], "ans": "Dolomite → ferroan dolomite → ankerite → siderite", "back": "The carbonate gets more iron-rich toward ore, with siderite closest."},
 {"id": "L9-cp11", "lecture": 9, "kind": "mc", "front": "Why do SEDEX deposits cluster in a few regions?", "opts": ["They form anywhere there is shale", "They need a rare combination: an enclosed, anoxic rift basin with aquifer, cap and focused faults, and where one basin has it, several deposits form", "They only formed in the last 100 million years"], "ans": "They need a rare combination: an enclosed, anoxic rift basin with aquifer, cap and focused faults, and where one basin has it, several deposits form", "back": "Find the right basin and you usually find more than one deposit, as around Mount Isa and McArthur River."},
 {"id": "L9-st1", "lecture": 9, "kind": "q", "lvl": "Recall", "front": "What is a SEDEX deposit? Give its main ore and gangue minerals and its typical host rock.", "back": "Zn-Pb-Ag deposits formed by venting of saline brine (about 80 to 200 °C) into a reduced sedimentary basin. Sphalerite and galena (Zn greater than Pb) with some silver; pyrite and pyrrhotite; barite gangue. Hosted by laminated, organic-rich black shale or dolomitic siltstone, with the sulphide in fine laminae."},
 {"id": "L9-st2", "lecture": 9, "kind": "q", "lvl": "Recall", "front": "List the five essentials a basin needs to make SEDEX deposits.", "back": "An extensional setting; structures that control basin architecture and fluid flow; thick basin fill (2 to 5 km of syn-rift clastics as aquifer, with a post-rift shale or carbonate aquitard); large-scale hydrothermal fluid flow (with a heat source); a stagnant water column containing H₂S."},
 {"id": "L9-st3", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "Explain the Goodfellow and Lydon model from rifting to ore.", "back": "A long-lived rift basin fills with permeable clastics (the aquifer), capped by reduced shale and chert (the aquitard). Heat drives brine convection, which leaches metals. The aquifer becomes overpressured and ruptures the cap; brine rises up active faults, mixes with H₂S in the anoxic water column, and forms vent-proximal and vent-distal deposits."},
 {"id": "L9-st4", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "Compare vent-proximal and vent-distal SEDEX deposits: fluid, features and an example of each.", "back": "Proximal: buoyant (or intermediate) brine, lower salinity, higher T, reduced; footwall alteration, breccia pipes, coarser sulphide; Sullivan. Distal: dense brine, higher salinity, lower T, oxidised, pooling in depressions; laminated sulphide, no footwall alteration, barite; HYC."},
 {"id": "L9-st5", "lecture": 9, "kind": "q", "lvl": "Think", "front": "Why are north Australian SEDEX deposits zinc- and lead-rich but copper-poor?", "back": "Their brines were oxidised and near neutral (hematitic sandstone aquifers), so they carried thousands of ppm Zn and Pb as chloride complexes. Copper solubility stays low, and the fluids stayed below about 300 °C, which limits copper."},
 {"id": "L9-st6", "lecture": 9, "kind": "q", "lvl": "Recall", "front": "Where do the fluid, the metals, the sulphur and the heat come from, and what do the isotopes say?", "back": "Fluid: evaporated seawater and dissolved halite. Metals: basin sediments, leached by convecting brine. Sulphur: H₂S in the anoxic seawater. Heat: mafic sills and dykes or another source. δ³⁴S ranges from -10 to +30‰; uniform, high-μ Pb isotopes point to upper-crustal rocks within the basin."},
 {"id": "L9-st7", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "Describe the stratified water column and how laminated ore builds up.", "back": "An oxic top layer (Fe³⁺ insoluble), a mixing layer where pyrite precipitates, and an anoxic, H₂S-rich bottom layer. Brine pulses, triggered by tectonism, meet H₂S and precipitate sphalerite and galena, which sink; between pulses, pelagic organic mud and carbonate mass flows add sediment layers."},
 {"id": "L9-st8", "lecture": 9, "kind": "q", "lvl": "Think", "front": "Contrast exhalative and replacement models for SEDEX. Which is favoured and why?", "back": "Exhalative: sulphide precipitates at the seafloor from vented brine. Replacement: sulphide replaces permeable layers below the seafloor, during diagenesis or later deformation; at MacMillan Pass, sulphide replaced earlier barite. Most deposits, especially the big ones, have sulphide laminae interbedded with sediment, favouring an exhalative, syngenetic origin."},
 {"id": "L9-st9", "lecture": 9, "kind": "q", "lvl": "Apply", "front": "What would you use to vector toward a hidden SEDEX ore body?", "back": "The Fe-Mn carbonate halo (dolomite to ferroan dolomite to ankerite to siderite toward ore); Mn and Tl halos found by assay; C, O and Sr isotope halos; pyritic shale with Fe-Mn-Zn enrichment; bedded barite and Ba:Zn rising away from the vent; Pb/Zn zoning; and deep syn-sedimentary faults."},
 {"id": "L9-st10", "lecture": 9, "kind": "q", "lvl": "Synthesise", "front": "Use HYC and Century to explain why a big SEDEX deposit can still be hard to turn into a mine.", "back": "HYC’s sulphides are extremely fine grained (some under 20 µm), intergrown with carbonaceous mud and silica, so fine-grinding technology was needed before it could be processed economically. Century is remote and floods in the wet season, so it needed a slurry pipeline to the Gulf to keep running around the clock. Grade and tonnage aren’t enough without processing and infrastructure."},
 /* Lecture 10: 33 terms, 11 checkpoints, 10 self-test */
 {"id": "L10-g-alteration-pipe", "lecture": 10, "kind": "term", "front": "Alteration pipe", "back": "The pipe-shaped zone of altered footwall rock (chlorite, silica, sericite) that fed fluid up to the mound."},
 {"id": "L10-g-anhydrite", "lecture": 10, "kind": "term", "front": "Anhydrite", "back": "CaSO₄; forms where hot fluid heats seawater, on the outside of chimneys."},
 {"id": "L10-g-barite", "lecture": 10, "kind": "term", "front": "Barite", "back": "BaSO₄; forms on top of and away from the mound at low temperature."},
 {"id": "L10-g-besshi-type", "lecture": 10, "kind": "term", "front": "Besshi-type", "back": "Cu-Zn ± Co VMS in mixed basalt and greywacke successions, between VMS and SEDEX."},
 {"id": "L10-g-bimodal", "lecture": 10, "kind": "term", "front": "Bimodal", "back": "A volcanic succession with two compositions, mafic and felsic, and little in between."},
 {"id": "L10-g-black-smoker", "lecture": 10, "kind": "term", "front": "Black smoker", "back": "A seafloor vent discharging fluid at around 350 °C, black with fine sulphide particles."},
 {"id": "L10-g-caldera", "lecture": 10, "kind": "term", "front": "Caldera", "back": "A circular depression formed when a volcano’s roof collapses into an emptied magma chamber."},
 {"id": "L10-g-carbonatisation", "lecture": 10, "kind": "term", "front": "Carbonatisation", "back": "Alteration adding carbonate; siderite near VMS ore, calcite further away."},
 {"id": "L10-g-chalcopyrite", "lecture": 10, "kind": "term", "front": "Chalcopyrite", "back": "CuFeS₂, the main copper mineral; brassy yellow; in the hot core and stringer zone."},
 {"id": "L10-g-chlorite", "lecture": 10, "kind": "term", "front": "Chlorite", "back": "A green sheet silicate; becomes Fe-rich and darker toward VMS ore."},
 {"id": "L10-g-cyprus-type", "lecture": 10, "kind": "term", "front": "Cyprus-type", "back": "Small Cu-Zn VMS in ophiolitic pillow basalts, like Troodos."},
 {"id": "L10-g-em-survey", "lecture": 10, "kind": "term", "front": "EM survey", "back": "Electromagnetic geophysical survey; detects conductive bodies such as massive sulphide."},
 {"id": "L10-g-exhalative", "lecture": 10, "kind": "term", "front": "Exhalative", "back": "Deposited from fluid vented (exhaled) onto the seafloor."},
 {"id": "L10-g-exhalite", "lecture": 10, "kind": "term", "front": "Exhalite", "back": "A thin chemical sediment (often silica) on top of a VMS lens, deposited as the system wanes."},
 {"id": "L10-g-galena", "lecture": 10, "kind": "term", "front": "Galena", "back": "PbS, the lead mineral; lead grey, very dense; at the cooler margins."},
 {"id": "L10-g-invisible-gold", "lecture": 10, "kind": "term", "front": "Invisible gold", "back": "Gold locked inside the crystal structure of pyrite or arsenopyrite, too fine to see."},
 {"id": "L10-g-kuroko-type", "lecture": 10, "kind": "term", "front": "Kuroko-type", "back": "Zn-Pb-Ag-rich VMS in felsic arc volcanics, like the Kuroko district of Japan."},
 {"id": "L10-g-lithotectonic-setting", "lecture": 10, "kind": "term", "front": "Lithotectonic setting", "back": "Classification by the volcanic and sedimentary units formed with the deposits in a district."},
 {"id": "L10-g-mound", "lecture": 10, "kind": "term", "front": "Mound", "back": "The pile of massive sulphide built on the seafloor around a vent field."},
 {"id": "L10-g-obduction", "lecture": 10, "kind": "term", "front": "Obduction", "back": "Thrusting of oceanic crust up onto continental crust instead of down a subduction zone."},
 {"id": "L10-g-ophiolite", "lecture": 10, "kind": "term", "front": "Ophiolite", "back": "A slice of oceanic crust and upper mantle thrust onto land."},
 {"id": "L10-g-pillow-lava", "lecture": 10, "kind": "term", "front": "Pillow lava", "back": "Rounded lava bodies formed by underwater eruption; a sign of a seafloor setting."},
 {"id": "L10-g-pyrrhotite", "lecture": 10, "kind": "term", "front": "Pyrrhotite", "back": "Fe₁₋ₓS, a magnetic iron sulphide; with chalcopyrite in the hot core."},
 {"id": "L10-g-remobilisation", "lecture": 10, "kind": "term", "front": "Remobilisation", "back": "Later movement of metals within or out of a deposit by hydrothermal fluid."},
 {"id": "L10-g-silicification", "lecture": 10, "kind": "term", "front": "Silicification", "back": "Alteration adding silica: loss of Fe, Mg, K and gain of Si, Na; quartz-albite-epidote."},
 {"id": "L10-g-sphalerite", "lecture": 10, "kind": "term", "front": "Sphalerite", "back": "(Zn,Fe)S, the zinc mineral; at the cooler margins."},
 {"id": "L10-g-spilitisation", "lecture": 10, "kind": "term", "front": "Spilitisation", "back": "Regional sodium alteration of basalt: gain Na, lose Ca; chlorite-sericite-albite-epidote-quartz."},
 {"id": "L10-g-stockwork", "lecture": 10, "kind": "term", "front": "Stockwork", "back": "A dense, criss-crossing network of veins; here the feeder below a VMS lens."},
 {"id": "L10-g-stringer-zone", "lecture": 10, "kind": "term", "front": "Stringer zone", "back": "The network of sulphide-bearing veins in altered footwall rock below a VMS lens; often copper-rich. Also called stockwork."},
 {"id": "L10-g-tetrahedrite", "lecture": 10, "kind": "term", "front": "Tetrahedrite", "back": "A Cu-Fe-Ag-Sb sulphosalt, an important silver carrier."},
 {"id": "L10-g-vms", "lecture": 10, "kind": "term", "front": "VMS", "back": "Volcanogenic massive sulphide: a polymetallic sulphide lens formed on or near the seafloor from hot fluid venting in a volcanic setting. Also VHMS or VAMS."},
 {"id": "L10-g-white-smoker", "lecture": 10, "kind": "term", "front": "White smoker", "back": "A cooler vent whose plume is pale with barite, silica or anhydrite rather than metal sulphide."},
 {"id": "L10-g-zone-refining", "lecture": 10, "kind": "term", "front": "Zone refining", "back": "Hot later fluid redissolving low-temperature sulphide in a mound’s core and reprecipitating it at the margins."},
 {"id": "L10-cp1", "lecture": 10, "kind": "mc", "front": "What separates VMS from SEDEX?", "opts": ["VMS is in volcanic rock, with fluid venting from volcanic hydrothermal systems; SEDEX is in sediment, with brine rising up basin faults", "VMS has no zinc", "VMS forms on land"], "ans": "VMS is in volcanic rock, with fluid venting from volcanic hydrothermal systems; SEDEX is in sediment, with brine rising up basin faults", "back": "Both are exhalative and submarine; the host rock and the fluid pathway differ."},
 {"id": "L10-cp2", "lecture": 10, "kind": "mc", "front": "Where are the largest VMS deposits?", "opts": ["Mid-ocean ridges in basalt", "Island arcs and back arcs, in felsic pyroclastic rocks", "Stable continental shields"], "ans": "Island arcs and back arcs, in felsic pyroclastic rocks", "back": "Arc settings bring more metal from the magma. All VMS settings are extensional."},
 {"id": "L10-cp3", "lecture": 10, "kind": "mc", "front": "Why does caldera collapse matter for VMS?", "opts": ["It cools the magma", "It suddenly depressurises the system and opens faults that focus fluid", "It buries the deposit too deep to mine"], "ans": "It suddenly depressurises the system and opens faults that focus fluid", "back": "Collapse faults are the pathways; the pressure drop drives venting."},
 {"id": "L10-cp4", "lecture": 10, "kind": "mc", "front": "Where do most of the metals come from?", "opts": ["Leached from the volcanic pile by heated seawater, with extra magmatic metal in arcs", "Seawater alone", "Meteorites"], "ans": "Leached from the volcanic pile by heated seawater, with extra magmatic metal in arcs", "back": "Oceanic crust has plenty of metal; arc magmas add more, partly by vapour transport."},
 {"id": "L10-cp5", "lecture": 10, "kind": "mc", "front": "In an ideal mound, where is the chalcopyrite?", "opts": ["At the margin and top", "In the hot core and the stringer zone below", "Only in the barite cap"], "ans": "In the hot core and the stringer zone below", "back": "Cu at about 350 °C in the core and stringer; Zn-Pb at the cooler margin; barite on top."},
 {"id": "L10-cp6", "lecture": 10, "kind": "mc", "front": "Why does Zn:Cu rise upward and outward?", "opts": ["The fluid cools away from the vent, dropping Cu first and Zn later", "Zinc is heavier", "Seawater adds zinc"], "ans": "The fluid cools away from the vent, dropping Cu first and Zn later", "back": "Progressive cooling: Cu-dominant to Zn-dominant zones."},
 {"id": "L10-cp7", "lecture": 10, "kind": "mc", "front": "Approaching VMS ore, chlorite becomes...", "opts": ["More Mg-rich and paler", "More Fe-rich and darker", "Absent"], "ans": "More Fe-rich and darker", "back": "Fe-rich, black chlorite is a vector toward mineralisation."},
 {"id": "L10-cp8", "lecture": 10, "kind": "mc", "front": "Which metal does VMS supply the biggest share of?", "opts": ["Gold, about 2%", "Copper, about 6%", "Zinc, about 22%"], "ans": "Zinc, about 22%", "back": "VMS gives about 22% of world zinc."},
 {"id": "L10-cp9", "lecture": 10, "kind": "mc", "front": "The most recognised VMS classification is based on...", "opts": ["metal ratios only", "the volcanic and sedimentary units formed with the deposits (lithotectonic setting)", "age"], "ans": "the volcanic and sedimentary units formed with the deposits (lithotectonic setting)", "back": "Five types: bimodal-mafic, mafic, pelitic-mafic, bimodal-felsic, siliciclastic-felsic."},
 {"id": "L10-cp10", "lecture": 10, "kind": "mc", "front": "Pillow basalt in an ophiolite, a massive pyrite lens over a Cu-rich stringer zone in chloritised basalt. Which style?", "opts": ["Kuroko", "Besshi", "Cyprus"], "ans": "Cyprus", "back": "Cyprus-type: small, Cu-Zn, in ophiolitic mafic volcanics like Troodos."},
 {"id": "L10-cp11", "lecture": 10, "kind": "mc", "front": "Why are lenses like Jaguar’s easy to find with geophysics?", "opts": ["They are magnetic", "They are almost pure sulphide and conduct electricity, so EM surveys pick them up", "They are radioactive"], "ans": "They are almost pure sulphide and conduct electricity, so EM surveys pick them up", "back": "About 99% sulphide: a strong conductor."},
 {"id": "L10-st1", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Define a VMS deposit and list its main metals and minerals.", "back": "A lens of polymetallic massive sulphide formed on or near the seafloor from focused discharge of hot, metal-rich hydrothermal fluid in a volcanic setting. Zn, Pb, Cu, Ag, Au (and Co, Sn, Se, Mn, Cd, In, Bi, Te, Ga, Ge). Pyrite, pyrrhotite, chalcopyrite, sphalerite, galena, barite."},
 {"id": "L10-st2", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Compare VMS and SEDEX deposits.", "back": "Both are submarine exhalative deposits that hold most of the world’s Zn and Pb. VMS: volcanic hosts, hotter fluid (about 350 °C) venting from volcanic hydrothermal cells, Cu-rich cores, genuinely massive sulphide. SEDEX: sedimentary hosts, cooler brines (100 to 200 °C) up basin faults, fine laminated Zn-Pb ore."},
 {"id": "L10-st3", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Which tectonic settings host VMS deposits, and which host the largest?", "back": "All extensional: mid-ocean ridges and continental rifts (mafic hosts), island arcs and back arcs (felsic hosts). The largest are in felsic pyroclastic rocks in arcs and back arcs."},
 {"id": "L10-st4", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Explain how a caldera helps form an arc VMS deposit.", "back": "Eruption empties the chamber, the roof collapses, the system depressurises instantly and ring faults open. Those faults channel seawater down and hot fluid up to vent sites; reactivation by new magma can drive further hydrothermal cycles."},
 {"id": "L10-st5", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Draw or describe an ideal VMS mound and its feeder.", "back": "A massive sulphide lens with a chalcopyrite ± pyrrhotite core (~350 °C), a sphalerite ± pyrite ± galena margin (250 to 150 °C), barite on top and often a thin silica exhalite; below it a Cu-rich stringer or stockwork zone in a chloritised, silicified alteration pipe."},
 {"id": "L10-st6", "lecture": 10, "kind": "q", "lvl": "Think", "front": "Why are real VMS deposits often not ideally zoned?", "back": "Remobilisation: later hot fluid redissolves metals and carries them to the margins or out into the sea, leaving pyrite-rich cores and thin metal-rich margins. Pulses: hot and cool pulses overprint, so high- and low-temperature mineral suites overlap."},
 {"id": "L10-st7", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Describe the four alteration styles around VMS ore and how each vectors toward ore.", "back": "Silicification (loss Fe, Mg, K; gain Si, Na), spilitisation (gain Na, lose Ca; chlorite more Fe-rich toward ore), carbonatisation (siderite proximal, calcite distal), epidote-quartz (amphibole and Al-rich epidote at higher T)."},
 {"id": "L10-st8", "lecture": 10, "kind": "q", "lvl": "Recall", "front": "Name the five lithotectonic VMS types and give one example of each.", "back": "Bimodal-mafic (Abitibi), mafic (Troodos), pelitic-mafic (Besshi, Windy Craggy), bimodal-felsic (Kuroko, Pilbara), siliciclastic-felsic (Iberian Belt, Teutonic Bore)."},
 {"id": "L10-st9", "lecture": 10, "kind": "q", "lvl": "Apply", "front": "Contrast Cyprus-, Kuroko- and Besshi-type deposits.", "back": "Cyprus: small Cu-Zn in ophiolitic pillow basalts at ridges. Kuroko: small to large, high-grade Zn-Pb-Ag-Sb in felsic arc volcanics, mound-shaped with coarse clastic sulphide. Besshi: mostly small, low-grade Cu-Zn ± Co sheets in greywacke with basalt, transitional to SEDEX."},
 {"id": "L10-st10", "lecture": 10, "kind": "q", "lvl": "Synthesise", "front": "Using Jaguar, explain how you would explore for and recognise a VMS deposit in an Archean greenstone belt.", "back": "Follow the prospective felsic-mafic contact along strike, since deposits cluster a few kilometres apart. Use EM surveys to find conductive massive sulphide. Underground or in core, look for increasing Fe-chlorite, bleaching and sulphide replacement of pillows, hematite flooding, and a chalcopyrite stringer zone below banded massive sulphide."},
 /* Lecture 11: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L11-g-a-vein", "lecture": 11, "kind": "term", "front": "A vein", "back": "An early, irregular sugary quartz-K-feldspar vein with a K-feldspar halo."},
 {"id": "L11-g-argillic-alteration", "lecture": 11, "kind": "term", "front": "Argillic alteration", "back": "Clay-rich alteration that destroys plagioclase; above the system, not always present."},
 {"id": "L11-g-b-vein", "lecture": 11, "kind": "term", "front": "B vein", "back": "A planar quartz vein with coarse crystals perpendicular to the walls and coarse molybdenite and chalcopyrite; no halo; carries most of the ore."},
 {"id": "L11-g-block-caving", "lecture": 11, "kind": "term", "front": "Block caving", "back": "Underground mining that undercuts a huge block so it caves under its own weight."},
 {"id": "L11-g-bornite", "lecture": 11, "kind": "term", "front": "Bornite", "back": "Cu₅FeS₄, a purple-iridescent copper sulphide."},
 {"id": "L11-g-breccia-pipe", "lecture": 11, "kind": "term", "front": "Breccia pipe", "back": "A pipe of broken rock made by explosive fluid release; can host high-grade ore."},
 {"id": "L11-g-carapace", "lecture": 11, "kind": "term", "front": "Carapace", "back": "The water-saturated outer shell of a crystallising intrusion."},
 {"id": "L11-g-cupola", "lecture": 11, "kind": "term", "front": "Cupola", "back": "The domed top of an intrusion."},
 {"id": "L11-g-d-vein", "lecture": 11, "kind": "term", "front": "D vein", "back": "A late pyrite-anhydrite vein with a sericite halo; cuts everything."},
 {"id": "L11-g-eb-vein", "lecture": 11, "kind": "term", "front": "EB vein", "back": "An early biotite vein, deep in the system."},
 {"id": "L11-g-enargite", "lecture": 11, "kind": "term", "front": "Enargite", "back": "Cu₃AsS₄, a copper arsenic sulphide common in porphyry systems."},
 {"id": "L11-g-flat-slab-subduction", "lecture": 11, "kind": "term", "front": "Flat-slab subduction", "back": "Shallow-angle subduction, linked to the largest porphyry deposits."},
 {"id": "L11-g-hydrofracturing", "lecture": 11, "kind": "term", "front": "Hydrofracturing", "back": "Rock breaking under fluid pressure; makes porphyry stockworks and breccias."},
 {"id": "L11-g-i-type", "lecture": 11, "kind": "term", "front": "I-type", "back": "A granitoid derived from igneous source rock rather than melted sediment."},
 {"id": "L11-g-magmatic-hydrothermal", "lecture": 11, "kind": "term", "front": "Magmatic-hydrothermal", "back": "Formed by hot fluid released from a crystallising magma."},
 {"id": "L11-g-mantle-wedge", "lecture": 11, "kind": "term", "front": "Mantle wedge", "back": "The wedge of mantle above a subducting slab, where hydrous melting makes arc magma."},
 {"id": "L11-g-mash-zone", "lecture": 11, "kind": "term", "front": "MASH zone", "back": "Melting, Assimilation, Storage, Homogenisation: the lower-crustal zone where arc basalt mixes with crust to make hybrid magma."},
 {"id": "L11-g-molybdenite", "lecture": 11, "kind": "term", "front": "Molybdenite", "back": "MoS₂, soft, platy, lead-grey: the ore of molybdenum."},
 {"id": "L11-g-ore-shell", "lecture": 11, "kind": "term", "front": "Ore shell", "back": "The zone around the barren core with 1 to 3% sulphide, more chalcopyrite than pyrite: the ore."},
 {"id": "L11-g-oxidised-magma", "lecture": 11, "kind": "term", "front": "Oxidised magma", "back": "A magma with high Fe³⁺/Fe²⁺ (near the hematite-magnetite buffer); carries Cu and Au to porphyry deposits."},
 {"id": "L11-g-phenocryst", "lecture": 11, "kind": "term", "front": "Phenocryst", "back": "A large crystal in a finer-grained groundmass."},
 {"id": "L11-g-phyllic-alteration", "lecture": 11, "kind": "term", "front": "Phyllic alteration", "back": "Quartz-sericite-pyrite alteration on the flanks; not always present."},
 {"id": "L11-g-porphyry", "lecture": 11, "kind": "term", "front": "Porphyry", "back": "An igneous rock with large crystals (phenocrysts) in a fine groundmass; also short for a porphyry ore deposit."},
 {"id": "L11-g-potassic-alteration", "lecture": 11, "kind": "term", "front": "Potassic alteration", "back": "K-feldspar and biotite (± magnetite) alteration in the porphyry core; always present."},
 {"id": "L11-g-propylitic-alteration", "lecture": 11, "kind": "term", "front": "Propylitic alteration", "back": "Chlorite-epidote-albite-calcite alteration in the outer halo; always present."},
 {"id": "L11-g-pyrite-shell", "lecture": 11, "kind": "term", "front": "Pyrite shell", "back": "The zone outside the ore shell with about 10% pyrite and little chalcopyrite."},
 {"id": "L11-g-sericite", "lecture": 11, "kind": "term", "front": "Sericite", "back": "Fine white mica made by hydrolytic alteration of feldspar."},
 {"id": "L11-g-skarn", "lecture": 11, "kind": "term", "front": "Skarn", "back": "A calc-silicate rock formed where intrusion-related fluid reacts with carbonate; can host Cu-Au-Fe or Pb-Zn-Ag ore."},
 {"id": "L11-g-sr-y", "lecture": 11, "kind": "term", "front": "Sr/Y", "back": "Strontium to yttrium ratio; high in hydrous, fertile porphyry magmas."},
 {"id": "L11-g-stockwork", "lecture": 11, "kind": "term", "front": "Stockwork", "back": "A dense, criss-crossing network of veinlets; the main ore style in porphyries."},
 {"id": "L11-g-supergene-blanket", "lecture": 11, "kind": "term", "front": "Supergene blanket", "back": "The enriched chalcocite-covellite zone formed by weathering; up to four times primary grade."},
 {"id": "L11-g-ust", "lecture": 11, "kind": "term", "front": "UST", "back": "Unidirectional solidification texture: comb-like crystal layers growing down from an intrusion’s roof; a vector to ore above."},
 {"id": "L11-cp1", "lecture": 11, "kind": "mc", "front": "Why can porphyry deposits be mined at 0.1 to 0.5% Cu?", "opts": ["Because they are enormous (hundreds to over a thousand Mt) and mined at huge scale for decades", "Because copper is rare", "Because the ore is at the surface only"], "ans": "Because they are enormous (hundreds to over a thousand Mt) and mined at huge scale for decades", "back": "Economies of scale over a long mine life make low grade pay."},
 {"id": "L11-cp2", "lecture": 11, "kind": "mc", "front": "Which porphyry phase carries most of the copper?", "opts": ["The largest intrusion", "The earliest phase; later phases dilute it", "The last phase"], "ans": "The earliest phase; later phases dilute it", "back": "Volume doesn’t predict copper; the earliest phase does."},
 {"id": "L11-cp3", "lecture": 11, "kind": "mc", "front": "What kind of magma makes a porphyry Cu-Au deposit?", "opts": ["Reduced and highly fractionated", "Oxidised, hydrous and little fractionated", "Dry basalt"], "ans": "Oxidised, hydrous and little fractionated", "back": "Oxidised (near hematite-magnetite) magma keeps Cu and Au out of early sulphide. Sn-W porphyries come from reduced magma."},
 {"id": "L11-cp4", "lecture": 11, "kind": "mc", "front": "Porphyritic texture means...", "opts": ["all crystals the same size", "large phenocrysts in a fine groundmass: slow growth at depth, then fast cooling at a high level", "glassy with no crystals"], "ans": "large phenocrysts in a fine groundmass: slow growth at depth, then fast cooling at a high level", "back": "The two-stage cooling of a shallow intrusion gives the deposits their name."},
 {"id": "L11-cp5", "lecture": 11, "kind": "mc", "front": "Drilling out from the centre of a porphyry, what order do you meet?", "opts": ["Ore shell, barren core, pyrite shell", "Barren or low-grade core, ore shell, pyrite shell, propylitic halo", "Pyrite shell, ore shell, propylitic halo"], "ans": "Barren or low-grade core, ore shell, pyrite shell, propylitic halo", "back": "The ore is on the margins of the intrusion, not in its middle."},
 {"id": "L11-cp6", "lecture": 11, "kind": "mc", "front": "Which veins carry the bulk of porphyry ore?", "opts": ["A veins", "B veins", "D veins"], "ans": "B veins", "back": "Planar, halo-free B veins with coarse molybdenite, chalcopyrite and bornite, often sheeted."},
 {"id": "L11-cp7", "lecture": 11, "kind": "mc", "front": "Pink K-feldspar and hydrothermal biotite mean...", "opts": ["propylitic alteration, outer halo", "potassic alteration, the core", "argillic alteration"], "ans": "potassic alteration, the core", "back": "Potassic is always present in the core; pink K-feldspar reflects iron in an oxidised system."},
 {"id": "L11-cp8", "lecture": 11, "kind": "mc", "front": "Why do Chuquicamata and El Abra sit on magnetic lows?", "opts": ["They are hosted in limestone", "Hydrothermal fluid destroyed the primary magnetite", "They are buried too deep"], "ans": "Hydrothermal fluid destroyed the primary magnetite", "back": "Fluid flushing demagnetised the rock; a low in a magnetic intrusion is a target."},
 {"id": "L11-cp9", "lecture": 11, "kind": "mc", "front": "What makes the porphyry stockwork?", "opts": ["Tectonic folding", "Hydrofracturing when water exsolved into the carapace builds enough pressure to break the rock", "Weathering"], "ans": "Hydrofracturing when water exsolved into the carapace builds enough pressure to break the rock", "back": "3 to 5% water concentrates in the carapace, pressure builds, the brittle roof fails."},
 {"id": "L11-cp10", "lecture": 11, "kind": "mc", "front": "Compared with Cu-Au porphyries, porphyry Mo deposits come from...", "opts": ["more oxidised, less fractionated magma", "more reduced, more fractionated magma", "mantle peridotite"], "ans": "more reduced, more fractionated magma", "back": "Climax is in rhyolitic porphyry; NSW porphyries are all oxidised Cu-Au types."},
 {"id": "L11-cp11", "lecture": 11, "kind": "mc", "front": "Which stress regime is ideal for porphyry Cu formation?", "opts": ["Pure tension", "Pure compression", "Shear, with pull-apart extensional conduits"], "ans": "Shear, with pull-apart extensional conduits", "back": "Shear focuses magma and fluid along local extensional faults."},
 {"id": "L11-st1", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "What are the five factors needed for any magmatic-hydrothermal deposit?", "back": "A source of metals, a transport mechanism, a concentration mechanism, a depositional mechanism, and a post-depositional history that preserves it."},
 {"id": "L11-st2", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "Give the size and grade of typical porphyry deposits and explain why they are economic.", "back": "Many >500 Mt, some >1000 Mt, at 0.1 to 0.5% Cu, ~0.3 g/t Au, up to ~0.5% Mo. Economic through enormous scale and long mine life (open pit or block caving), which also smooths out metal price swings."},
 {"id": "L11-st3", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "Explain how subduction produces an oxidised, metal-bearing porphyry magma.", "back": "Hydrated oceanic crust dehydrates (amphibole, serpentine), releasing oxidising fluid rich in Cl, S, LILE, Cu and Au into the mantle wedge, which melts. Basalt ponds in a lower-crustal MASH zone, mixing with crust into hybrid calc-alkaline magma that rises to high-level stocks."},
 {"id": "L11-st4", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "Describe the Lowell and Guilbert zoning model.", "back": "Barren or low-grade potassic core with magnetite; ore shell (1 to 3% sulphide, cpy > py, molybdenite); pyrite shell (~10% py) with phyllic alteration; outer propylitic halo with peripheral Pb-Zn-Ag-Au veins; argillic alteration above. Potassic and propylitic always present; phyllic and argillic not always."},
 {"id": "L11-st5", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "Distinguish EB, A, B and D veins.", "back": "EB: early biotite veins, deep. A: early, irregular, sugary quartz-K-feldspar with K-feldspar halos. B: planar quartz with crystals perpendicular to walls, coarse molybdenite-chalcopyrite-bornite, no halo, most of the ore. D: late pyrite-anhydrite with sericite halos, cut everything."},
 {"id": "L11-st6", "lecture": 11, "kind": "q", "lvl": "Think", "front": "Why might a big porphyry stock have little copper?", "back": "Volume doesn’t control copper. Later intrusive phases dilute the earliest, metal-bearing phase, and late sericite or chlorite-sericite fluids can remove copper introduced during potassic alteration."},
 {"id": "L11-st7", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "List three exploration vectors toward porphyry ore and explain each.", "back": "Alteration zoning (pyrite shell outside, barren potassic core inside); UST textures (ore 100 to 200 m above, per slide 33); high Sr/Y fertile magmas (water suppresses plagioclase); magnetic lows where fluid destroyed magnetite in a magnetic intrusion; B-vein density."},
 {"id": "L11-st8", "lecture": 11, "kind": "q", "lvl": "Apply", "front": "Explain how a porphyry stockwork and breccia form.", "back": "A magma with 3 to 5% water at ~1000 °C crystallises; water concentrates in a saturated carapace; pressure builds until the brittle roof hydrofractures, making stockwork veins and breccia pipes; meteoric water then mixes in and drives sericitic alteration."},
 {"id": "L11-st9", "lecture": 11, "kind": "q", "lvl": "Recall", "front": "How do porphyry Mo deposits differ from porphyry Cu-Au deposits?", "back": "More reduced and more fractionated magmas; three host subclasses (granitic, trondhjemite, rhyolitic like Climax); ore mostly stockwork molybdenite at 0.1 to 0.45% MoS₂, 50 to 1500 Mt, mainly western North America."},
 {"id": "L11-st10", "lecture": 11, "kind": "q", "lvl": "Synthesise", "front": "Why are the central Andes the world’s largest copper province, and why are old porphyries rare?", "back": "Maximum shortening and oroclinal bending, Juan Fernandez ridge subduction (flat slab), repeated metallogenic episodes over a Cu-rich crust, and young Cenozoic age so they’re preserved. Porphyries form high in uplifting arcs and erode quickly, so Palaeozoic and older ones are rare."},
 /* Lecture 12: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L12-g-adularia", "lecture": 12, "kind": "term", "front": "Adularia", "back": "A low-temperature K-feldspar; marks near-neutral low-sulphidation epithermal systems."},
 {"id": "L12-g-alunite", "lecture": 12, "kind": "term", "front": "Alunite", "back": "A potassium aluminium sulphate; always marks low-pH alteration."},
 {"id": "L12-g-aurostibite", "lecture": 12, "kind": "term", "front": "Aurostibite", "back": "AuSb₂, a gold-antimony alloy, fairly common in orogenic gold deposits."},
 {"id": "L12-g-bisulphide-complex", "lecture": 12, "kind": "term", "front": "Bisulphide complex", "back": "Dissolved gold bonded to HS⁻ (Au(HS)₂⁻); dominant in near-neutral, reducing, cooler fluids."},
 {"id": "L12-g-boiling", "lecture": 12, "kind": "term", "front": "Boiling", "back": "Separation of vapour from a hydrothermal liquid as pressure drops near the surface; destabilises gold complexes."},
 {"id": "L12-g-calaverite", "lecture": 12, "kind": "term", "front": "Calaverite", "back": "AuTe₂, the commonest gold telluride."},
 {"id": "L12-g-carbon-in-pulp", "lecture": 12, "kind": "term", "front": "Carbon-in-pulp", "back": "Gold recovery that adsorbs dissolved gold onto activated carbon in a slurry; made low-grade ore economic from the 1980s."},
 {"id": "L12-g-carlin-type", "lecture": 12, "kind": "term", "front": "Carlin-type", "back": "Disseminated, very fine-grained gold in silicified sedimentary rocks, mined in bulk."},
 {"id": "L12-g-chloride-complex", "lecture": 12, "kind": "term", "front": "Chloride complex", "back": "Dissolved gold bonded to chloride (AuCl₂⁻); dominant in oxidising, acid, hotter fluids."},
 {"id": "L12-g-connate-water", "lecture": 12, "kind": "term", "front": "Connate water", "back": "Water trapped in sediment pores, modified by burial."},
 {"id": "L12-g-effervescence", "lecture": 12, "kind": "term", "front": "Effervescence", "back": "Unmixing of an H₂O-CO₂ fluid into water and CO₂ as pressure drops at depth."},
 {"id": "L12-g-electrum", "lecture": 12, "kind": "term", "front": "Electrum", "back": "A mining term for gold-silver alloy between Au75Ag25 and Au25Ag75."},
 {"id": "L12-g-en-echelon-veins", "lecture": 12, "kind": "term", "front": "En echelon veins", "back": "Parallel, overlapping vein segments in a stepped array, typical of shear zones."},
 {"id": "L12-g-epithermal", "lecture": 12, "kind": "term", "front": "Epithermal", "back": "Formed at shallow depth (surface to about 2 km) and low temperature (100 to 300 °C)."},
 {"id": "L12-g-fault-valve", "lecture": 12, "kind": "term", "front": "Fault valve", "back": "A fault that seals between earthquakes so fluid pressure builds, then opens and drains it."},
 {"id": "L12-g-fluid-mixing", "lecture": 12, "kind": "term", "front": "Fluid mixing", "back": "Combining two fluids of different chemistry, such as deep ore fluid and oxygenated groundwater, which can drop gold."},
 {"id": "L12-g-hydrostatic-pressure", "lecture": 12, "kind": "term", "front": "Hydrostatic pressure", "back": "Pressure from a connected column of fluid to the surface; lower than lithostatic."},
 {"id": "L12-g-invisible-gold", "lecture": 12, "kind": "term", "front": "Invisible gold", "back": "Gold in submicroscopic clusters or inside the pyrite or arsenopyrite lattice."},
 {"id": "L12-g-lithostatic-pressure", "lecture": 12, "kind": "term", "front": "Lithostatic pressure", "back": "Pressure from the weight of the overlying rock."},
 {"id": "L12-g-magmatic-water", "lecture": 12, "kind": "term", "front": "Magmatic water", "back": "Water derived from magma; the hottest and most saline crustal fluid."},
 {"id": "L12-g-maldonite", "lecture": 12, "kind": "term", "front": "Maldonite", "back": "Au₂Bi, a gold-bismuth alloy named after Maldon, Victoria."},
 {"id": "L12-g-mesothermal", "lecture": 12, "kind": "term", "front": "Mesothermal", "back": "Formed at intermediate depth and temperature; often used for orogenic gold."},
 {"id": "L12-g-metamorphic-water", "lecture": 12, "kind": "term", "front": "Metamorphic water", "back": "Water released by dehydration and decarbonation reactions above about 200 °C; low salinity, with CO₂."},
 {"id": "L12-g-meteoric-water", "lecture": 12, "kind": "term", "front": "Meteoric water", "back": "Water from the hydrological cycle (rain, groundwater, lakes, ice); dilute and oxygenated."},
 {"id": "L12-g-orogenic-gold", "lecture": 12, "kind": "term", "front": "Orogenic gold", "back": "Gold deposits formed by metamorphic fluids along faults in deformed terrains, 2 to 20 km deep."},
 {"id": "L12-g-paleoplacer", "lecture": 12, "kind": "term", "front": "Paleoplacer", "back": "An ancient placer preserved as lithified, often buried rock, like the Witwatersrand conglomerates."},
 {"id": "L12-g-placer", "lecture": 12, "kind": "term", "front": "Placer", "back": "A deposit of heavy minerals such as gold concentrated by rivers or waves."},
 {"id": "L12-g-seismic-pumping", "lecture": 12, "kind": "term", "front": "Seismic pumping", "back": "Fluid surging up a fault each time an earthquake opens it."},
 {"id": "L12-g-telluride", "lecture": 12, "kind": "term", "front": "Telluride", "back": "A compound of tellurium; gold tellurides include calaverite AuTe₂, petzite and sylvanite."},
 {"id": "L12-g-troy-ounce", "lecture": 12, "kind": "term", "front": "Troy ounce", "back": "The unit gold is priced in: about 31.1 g; one tonne holds 32 150.7 ounces."},
 {"id": "L12-g-uraninite", "lecture": 12, "kind": "term", "front": "Uraninite", "back": "UO₂; detrital uraninite in the Witwatersrand implies an oxygen-poor Archean atmosphere."},
 {"id": "L12-g-witwatersrand", "lecture": 12, "kind": "term", "front": "Witwatersrand", "back": "South African Archean conglomerate basin that has supplied about 40% of all gold ever mined."},
 {"id": "L12-cp1", "lecture": 12, "kind": "mc", "front": "Why is gold found in so many deposit types?", "opts": ["It is very common in the crust", "It can be carried by different complexes across a wide range of temperature, pH and redox, and drops out when fluids change", "It only forms in one setting, then moves"], "ans": "It can be carried by different complexes across a wide range of temperature, pH and redox, and drops out when fluids change", "back": "Chloride and bisulphide complexes let gold travel almost anywhere a hydrothermal fluid goes."},
 {"id": "L12-cp2", "lecture": 12, "kind": "mc", "front": "Which deposit has supplied about 40% of all gold ever mined?", "opts": ["Kalgoorlie", "Witwatersrand", "Carlin"], "ans": "Witwatersrand", "back": "About 45 000 t since 1886."},
 {"id": "L12-cp3", "lecture": 12, "kind": "mc", "front": "One tonne of gold holds about how many troy ounces?", "opts": ["1000", "32 150", "100 000"], "ans": "32 150", "back": "32 150.7 oz, so an ounce is about 31.1 g."},
 {"id": "L12-cp4", "lecture": 12, "kind": "mc", "front": "What happens to gold in rocks as metamorphic grade rises?", "opts": ["It increases", "It decreases: amphibolite-facies rocks hold 50 to 80% less than their protoliths", "It stays the same"], "ans": "It decreases: amphibolite-facies rocks hold 50 to 80% less than their protoliths", "back": "Metamorphic fluids strip it out, the gold that orogenic deposits collect."},
 {"id": "L12-cp5", "lecture": 12, "kind": "mc", "front": "Which fluid is low salinity and carries CO₂ from dehydration and decarbonation above about 200 °C?", "opts": ["Seawater", "Metamorphic water", "Connate water"], "ans": "Metamorphic water", "back": "Metamorphic water: the fluid behind orogenic gold."},
 {"id": "L12-cp6", "lecture": 12, "kind": "mc", "front": "In a near-neutral, reducing, 250 °C fluid, gold travels mainly as...", "opts": ["AuCl₂⁻", "Au(HS)₂⁻", "native gold particles"], "ans": "Au(HS)₂⁻", "back": "Bisulphide complexes dominate in near-neutral, reducing, cooler fluids."},
 {"id": "L12-cp7", "lecture": 12, "kind": "mc", "front": "Which of these is NOT a main gold deposition mechanism?", "opts": ["Boiling", "Mixing with oxygenated groundwater", "Slowly adding more chloride at constant conditions"], "ans": "Slowly adding more chloride at constant conditions", "back": "Gold drops out when the fluid changes: boiling, mixing, pressure drop, wall-rock reaction, cooling."},
 {"id": "L12-cp8", "lecture": 12, "kind": "mc", "front": "At what depth range do epithermal deposits form?", "opts": ["Surface to about 2 km", "5 to 20 km", "Below the Moho"], "ans": "Surface to about 2 km", "back": "Epithermal is shallow; porphyry a few kilometres down; orogenic deeper."},
 {"id": "L12-cp9", "lecture": 12, "kind": "mc", "front": "Under the IMA 50:50 rule, a grain with 40% Au and 60% Ag is called...", "opts": ["gold", "silver", "electrum"], "ans": "silver", "back": "Under 50% Au it is silver; electrum is only a mining term."},
 {"id": "L12-cp10", "lecture": 12, "kind": "mc", "front": "Which observation is a puzzle for a simple placer origin of the Wits gold?", "opts": ["Rounded quartz pebbles", "No granite or greenstone clasts, though the basin sits on granite and greenstone", "Gold in the conglomerate matrix"], "ans": "No granite or greenstone clasts, though the basin sits on granite and greenstone", "back": "The monomictic quartz-chert-pyrite clasts are hard to explain; the best fit is a hydrothermally modified paleoplacer."},
 {"id": "L12-cp11", "lecture": 12, "kind": "mc", "front": "Why have companies returned to old goldfields?", "opts": ["To mine low-grade material the old-timers left, by bulk methods", "Because the visible gold is still there", "Because placer gold regrows"], "ans": "To mine low-grade material the old-timers left, by bulk methods", "back": "Old miners took high-grade reefs; bulk mining makes the low grade pay."},
 {"id": "L12-st1", "lecture": 12, "kind": "q", "lvl": "Recall", "front": "List the three main families of gold-only deposits with an example of each.", "back": "Magmatic-hydrothermal (porphyry-related and epithermal: Kidston, Lihir), metamorphic (orogenic and intrusion-related: Yilgarn, Victoria, Carlin), sedimentary (placer and paleoplacer: possibly Witwatersrand)."},
 {"id": "L12-st2", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Calculate the gross value of a 20 Mt deposit at 1.5 g/t Au at US$4000 per ounce.", "back": "20 000 000 t × 1.5 g/t = 30 000 000 g = 30 t of gold; × 32 150.7 = about 965 000 oz; × US$4000 = about US$3.9 billion gross, before costs."},
 {"id": "L12-st3", "lecture": 12, "kind": "q", "lvl": "Think", "front": "Why do sulphur-undersaturated igneous rocks hold more gold than MORB?", "back": "Gold follows sulphide. MORB is more reduced, saturates in sulphide early and loses gold to it; sulphur-undersaturated (more oxidised) arc and ocean-island magmas keep gold in the melt."},
 {"id": "L12-st4", "lecture": 12, "kind": "q", "lvl": "Recall", "front": "Name the five crustal fluids and give one distinctive property of each.", "back": "Magmatic (hottest, most saline), seawater (3.5 wt% salts, 98% of free water), meteoric (dilute, oxygenated, from rain), connate (trapped pore water, modified by burial), metamorphic (from dehydration and decarbonation above ~200 °C, low salinity, CO₂)."},
 {"id": "L12-st5", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Explain why gold forms deposits across a wider temperature range than Cu or Zn.", "back": "Gold is fairly soluble at all temperatures: as bisulphide at low T and chloride at high T. Cu and Zn are mainly soluble as chloride at high T (>250 °C) and are insoluble in alkaline fluid, whereas gold dissolves in both acid and alkaline fluids."},
 {"id": "L12-st6", "lecture": 12, "kind": "q", "lvl": "Recall", "front": "List six ways gold is deposited from solution.", "back": "Boiling (or effervescence at depth), mixing with oxygenated groundwater, mixing with bicarbonate water, mixing with low-pH water, pressure drop, reaction with wall rock (neutralisation, oxidation), rapid cooling."},
 {"id": "L12-st7", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Describe the fault-valve mechanism and the veins it produces.", "back": "Between earthquakes a fault seals and fluid pressure rises from hydrostatic toward lithostatic. An earthquake ruptures it, pressure drops, fluid surges up and effervesces or cools, depositing quartz and gold. Repeated cycles build laminated veins and en echelon vein arrays."},
 {"id": "L12-st8", "lecture": 12, "kind": "q", "lvl": "Apply", "front": "Compare orogenic, epithermal and Carlin-type gold in setting, depth and temperature.", "back": "Orogenic: compressional deformed metamorphic terrains, 2 to 20 km, 200 to 700 °C. Epithermal: arcs, surface to 2 km, 100 to 300 °C. Carlin: post-orogenic back arc extension, 2 to 3 km, 200 to 300 °C, very fine gold in silicified sediments."},
 {"id": "L12-st9", "lecture": 12, "kind": "q", "lvl": "Think", "front": "Why does gold composition matter at Hera?", "back": "Grains range from about 27% to 96% Au. With gold at ~US$4000 and silver ~US$44 an ounce, low-gold grains are worth a fraction as much, so the payable value depends on knowing the gold chemistry before mining."},
 {"id": "L12-st10", "lecture": 12, "kind": "q", "lvl": "Synthesise", "front": "Summarise the evidence and models for the origin of the Witwatersrand gold.", "back": "Quartz-pebble conglomerates with gold and uraninite in the matrix; angular fine gold; no granite or greenstone clasts; pervasive alteration (pyrophyllite, chloritoid, pyrite). Paleoplacer (Frimmel) vs hydrothermal (Phillips); best fit is a hydrothermally modified paleoplacer. Heinrich (2015): volcanic acid rain, anoxic rivers and microbial mats trapped gold before atmospheric oxygenation."},
 /* Lecture 13: 32 terms, 11 checkpoints, 10 self-test */
 {"id": "L13-g-amphibolite-facies", "lecture": 13, "kind": "term", "front": "Amphibolite facies", "back": "Medium to high-grade metamorphism (hornblende, plagioclase, garnet), above greenschist."},
 {"id": "L13-g-ankerite", "lecture": 13, "kind": "term", "front": "Ankerite", "back": "Ca(Fe,Mg)(CO₃)₂, an iron carbonate common in orogenic gold alteration."},
 {"id": "L13-g-aquitard", "lecture": 13, "kind": "term", "front": "Aquitard", "back": "An impermeable layer or body that holds fluid back, such as the Walhalla dolerite dyke."},
 {"id": "L13-g-arsenian-pyrite", "lecture": 13, "kind": "term", "front": "Arsenian pyrite", "back": "Pyrite with arsenic in its structure, which can hold invisible gold."},
 {"id": "L13-g-arsenopyrite", "lecture": 13, "kind": "term", "front": "Arsenopyrite", "back": "FeAsS, a silver-white arsenic sulphide; a carrier of gold in orogenic and Carlin deposits."},
 {"id": "L13-g-carlin-type", "lecture": 13, "kind": "term", "front": "Carlin-type", "back": "Very fine, invisible gold in arsenian pyrite in silicified sedimentary rock; treated here as a subtype of orogenic gold."},
 {"id": "L13-g-crustal-continuum", "lecture": 13, "kind": "term", "front": "Crustal continuum", "back": "Groves’ idea that orogenic gold forms at every crustal level, from sub-greenschist to amphibolite facies."},
 {"id": "L13-g-deposit", "lecture": 13, "kind": "term", "front": "Deposit", "back": "Rock that has been mined or holds a proven economic resource not yet mined."},
 {"id": "L13-g-field", "lecture": 13, "kind": "term", "front": "Field", "back": "A group of deposits or mines with a similar geological setting."},
 {"id": "L13-g-fuchsite", "lecture": 13, "kind": "term", "front": "Fuchsite", "back": "A bright green chromium mica; in carbonate-altered rock it is a strong sign of orogenic gold."},
 {"id": "L13-g-greenschist-facies", "lecture": 13, "kind": "term", "front": "Greenschist facies", "back": "Low-grade metamorphism (chlorite, epidote, actinolite, albite), roughly 300 to 450 °C."},
 {"id": "L13-g-kink-fold", "lecture": 13, "kind": "term", "front": "Kink fold", "back": "A sharp, angular fold in foliated rock."},
 {"id": "L13-g-leatherjacket", "lecture": 13, "kind": "term", "front": "Leatherjacket", "back": "A thin, flat quartz vein in the Ballarat style."},
 {"id": "L13-g-lode-gold", "lecture": 13, "kind": "term", "front": "Lode gold", "back": "Gold in veins or lodes rather than in placer gravels."},
 {"id": "L13-g-metamorphic-hosted", "lecture": 13, "kind": "term", "front": "Metamorphic-hosted", "back": "Hosted by metamorphosed rocks; an older name for orogenic gold."},
 {"id": "L13-g-mine", "lecture": 13, "kind": "term", "front": "Mine", "back": "An area from which ore was or is being extracted."},
 {"id": "L13-g-muruntau", "lecture": 13, "kind": "term", "front": "Muruntau", "back": "Uzbekistan; the largest orogenic gold deposit, about 150 Moz."},
 {"id": "L13-g-nugget", "lecture": 13, "kind": "term", "front": "Nugget", "back": "A detrital lump of gold from a placer; Holtermann’s was really a gold-rich quartz vein."},
 {"id": "L13-g-orogenic-gold", "lecture": 13, "kind": "term", "front": "Orogenic gold", "back": "Structurally controlled gold deposits formed during regional metamorphism and deformation in mountain building, 2 to 20 km deep."},
 {"id": "L13-g-post-kinematic", "lecture": 13, "kind": "term", "front": "Post-kinematic", "back": "Formed after a deformation event; the Lachlan gold veins are post-kinematic."},
 {"id": "L13-g-pre-kinematic", "lecture": 13, "kind": "term", "front": "Pre-kinematic", "back": "Formed before a deformation event."},
 {"id": "L13-g-prospect", "lecture": 13, "kind": "term", "front": "Prospect", "back": "Mineralised rock not yet proven economic."},
 {"id": "L13-g-regolith", "lecture": 13, "kind": "term", "front": "Regolith", "back": "The weathered and transported material above fresh bedrock; very thick in the Yilgarn."},
 {"id": "L13-g-retrograde-metamorphism", "lecture": 13, "kind": "term", "front": "Retrograde metamorphism", "back": "Mineral changes as metamorphic rocks cool; most orogenic gold arrives during retrograde amphibolite to greenschist conditions."},
 {"id": "L13-g-saddle-reef", "lecture": 13, "kind": "term", "front": "Saddle reef", "back": "A quartz-gold reef in the hinge of an anticline, as at Bendigo."},
 {"id": "L13-g-seismic-pumping", "lecture": 13, "kind": "term", "front": "Seismic pumping", "back": "Fluid surging up a fault each time an earthquake opens it."},
 {"id": "L13-g-sericite", "lecture": 13, "kind": "term", "front": "Sericite", "back": "Fine white mica from feldspar breakdown; common in gold alteration."},
 {"id": "L13-g-silicification", "lecture": 13, "kind": "term", "front": "Silicification", "back": "Replacement of rock by silica; intense in Carlin-type deposits."},
 {"id": "L13-g-subsidiary-structure", "lecture": 13, "kind": "term", "front": "Subsidiary structure", "back": "A smaller fault or shear branching off a major crustal fault; where most orogenic gold sits."},
 {"id": "L13-g-syn-kinematic", "lecture": 13, "kind": "term", "front": "Syn-kinematic", "back": "Formed during a deformation event."},
 {"id": "L13-g-transpression", "lecture": 13, "kind": "term", "front": "Transpression", "back": "Compression combined with strike-slip movement."},
 {"id": "L13-g-workings", "lecture": 13, "kind": "term", "front": "Workings", "back": "Excavations made only to find or extract ore."},
 {"id": "L13-cp1", "lecture": 13, "kind": "mc", "front": "What makes a deposit “orogenic” gold?", "opts": ["Gold in river gravels", "Structurally controlled gold formed during regional metamorphism and deformation in mountain building", "Gold in a porphyry stock"], "ans": "Structurally controlled gold formed during regional metamorphism and deformation in mountain building", "back": "Veins and lodes along structures, 2 to 20 km deep, in compressional to transpressional settings."},
 {"id": "L13-cp2", "lecture": 13, "kind": "mc", "front": "When does most orogenic gold arrive?", "opts": ["During peak amphibolite metamorphism", "During retrograde amphibolite-to-greenschist conditions, often up to 100 Myr after the main orogeny", "Before any deformation"], "ans": "During retrograde amphibolite-to-greenschist conditions, often up to 100 Myr after the main orogeny", "back": "Gold is late in the orogenic cycle."},
 {"id": "L13-cp3", "lecture": 13, "kind": "mc", "front": "Which Precambrian craton has produced over 50 Moz of orogenic gold?", "opts": ["Yilgarn", "Kaapvaal", "Pilbara"], "ans": "Yilgarn", "back": "With the Superior and West African cratons, it’s one of the big three."},
 {"id": "L13-cp4", "lecture": 13, "kind": "mc", "front": "Why wasn’t Holtermann’s “nugget” a true nugget?", "opts": ["It was gold-plated", "It was a slab of quartz vein riddled with gold, not a detrital placer lump", "It was found at sea"], "ans": "It was a slab of quartz vein riddled with gold, not a detrital placer lump", "back": "A 3000 oz piece of vein from Hawkins Hill, 1872."},
 {"id": "L13-cp5", "lecture": 13, "kind": "mc", "front": "Where does Yilgarn gold usually sit?", "opts": ["On the main crustal faults", "On subsidiary structures branching off them, often at intersections", "Only in granite"], "ans": "On subsidiary structures branching off them, often at intersections", "back": "Structure and timing matter more than host rock."},
 {"id": "L13-cp6", "lecture": 13, "kind": "mc", "front": "At Bendigo, where are the saddle reefs?", "opts": ["In the hinges of anticlines", "In syncline troughs only", "In the granite"], "ans": "In the hinges of anticlines", "back": "Anticline hinges close off and trap the fluid."},
 {"id": "L13-cp7", "lecture": 13, "kind": "mc", "front": "At Stawell, why is gold concentrated around the basalt dome?", "opts": ["Basalt holds the most gold", "Rigid basalt barely deforms while sediments fold around it, opening voids that fill with veins", "The basalt is younger"], "ans": "Rigid basalt barely deforms while sediments fold around it, opening voids that fill with veins", "back": "Strength contrast creates dilation."},
 {"id": "L13-cp8", "lecture": 13, "kind": "mc", "front": "Muruntau is famous as...", "opts": ["the largest orogenic gold deposit (~150 Moz) and largest open-cut gold mine", "a Carlin-type deposit", "a paleoplacer"], "ans": "the largest orogenic gold deposit (~150 Moz) and largest open-cut gold mine", "back": "Found from soil As-Au anomalies in 1958; mined since 1967."},
 {"id": "L13-cp9", "lecture": 13, "kind": "mc", "front": "According to this lecture, where does orogenic gold itself come from?", "opts": ["Meteorites", "Pyrite micro-inclusions in carbonaceous mudstones and shales, released during metamorphism", "Seawater"], "ans": "Pyrite micro-inclusions in carbonaceous mudstones and shales, released during metamorphism", "back": "Fluids may be granite-derived; the gold is gathered from the country rocks."},
 {"id": "L13-cp10", "lecture": 13, "kind": "mc", "front": "Why can’t you see the gold in Carlin ore?", "opts": ["It is in tellurides", "It is invisible, locked in arsenian pyrite rims", "It weathered away"], "ans": "It is invisible, locked in arsenian pyrite rims", "back": "You see the arsenic and antimony minerals, not the gold."},
 {"id": "L13-cp11", "lecture": 13, "kind": "mc", "front": "At Tuena, which vein generation carries the gold?", "opts": ["Early, pre-kinematic, rootless veins", "Folded syn-kinematic veins", "Late, post-kinematic, planar carbonate-rich veins"], "ans": "Late, post-kinematic, planar carbonate-rich veins", "back": "Typical across the Lachlan: gold is late."},
 {"id": "L13-st1", "lecture": 13, "kind": "q", "lvl": "Recall", "front": "Define orogenic gold and give its key characteristics.", "back": "Structurally controlled vein (lode) gold formed during regional metamorphism and deformation in orogenesis; compressional to transpressional margins; 200 to 700 °C, 2 to 20 km; dilute H₂O-CO₂ ± CH₄, N₂ fluids; quartz veins with carbonate, sericite, arsenopyrite, pyrite, ± fuchsite; Archean to Mesozoic."},
 {"id": "L13-st2", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Explain the “crustal continuum”.", "back": "Orogenic gold forms at every crustal level, from sub-greenschist to amphibolite facies, with brittle veins and breccias at shallow levels, brittle-ductile shears in the middle and ductile shear zones deep; Au-Sb shallow, Au-As (-W) deep."},
 {"id": "L13-st3", "lecture": 13, "kind": "q", "lvl": "Think", "front": "Why do orogenic orebodies have great vertical but small lateral extent?", "back": "They form in large, deep, steep faults and shear zones, so the ore follows the structure down for kilometres while staying narrow; some Kalgoorlie mines go below 2 km."},
 {"id": "L13-st4", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Compare the Yilgarn and Victorian goldfields.", "back": "Yilgarn: Archean (2.7 Ga) granite-greenstone, gold in mafic volcanics, BIF and granite on subsidiary structures, deep regolith. Victoria: Palaeozoic Lachlan turbidites, greenschist facies, little visible alteration, fault-bounded zones, saddle reefs (Bendigo), bedding-cleavage control (Ballarat); gold Ordovician to Devonian."},
 {"id": "L13-st5", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Why does Bendigo’s gold sit in anticline hinges?", "back": "Folding opens dilatant zones in anticline hinges, which also act as traps that close off rising fluid; crosscutting shears feed fluid into them, forming saddle reefs."},
 {"id": "L13-st6", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "What controls gold around dolerite dykes and basalt domes?", "back": "They are rigid and impermeable: fluid is dammed against them (aquitard), and strength contrast with deforming sediments opens voids along their margins, as at Walhalla and Stawell."},
 {"id": "L13-st7", "lecture": 13, "kind": "q", "lvl": "Think", "front": "Summarise the evidence for fluid and gold sources in orogenic deposits.", "back": "Fluids: magmatic sulphur isotopes and granite trace elements (Bi, Te, As, Mo, Sb, Sn, W) suggest buried granites, though metamorphic fluids are the older view. Gold: pyrite micro-inclusions in carbonaceous mudstones released during metamorphism; Finnish transects show gold rising toward deposits."},
 {"id": "L13-st8", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "How do Carlin-type deposits differ from typical orogenic deposits?", "back": "Hosted in sub-greenschist argillites and limestones, 2 to 3 km, 200 to 300 °C, Cenozoic back-arc extension; intense silicification, some kaolinisation; invisible gold in arsenian pyrite rims; mined in bulk by open cut."},
 {"id": "L13-st9", "lecture": 13, "kind": "q", "lvl": "Apply", "front": "Calculate the value of Bendigo’s 700 000 kg of gold at US$4000 an ounce.", "back": "700 000 kg = 700 t × 32 150.7 oz/t = about 22.5 Moz × US$4000 = about US$90 billion (the slide gives about US$120 billion at a higher assumed price)."},
 {"id": "L13-st10", "lecture": 13, "kind": "q", "lvl": "Synthesise", "front": "Using Tuena, explain how you would decide which veins to target in an orogenic goldfield.", "back": "Map vein generations by crosscutting and deformation: early pre-kinematic rootless veins, syn-kinematic folded veins, and late post-kinematic planar carbonate veins that cut the foliation. In the Lachlan the gold is in the late set, so target late, undeformed veins along subsidiary faults in the main structural corridor."}
];

/* ---- hand-written cards below: kept when tools/build_cards.py reruns ---- */
CARDS.push(
 {"id": "L1-x-chain", "lecture": 1, "kind": "q", "front": "Name the links in the hydrothermal chain.", "back": "A metal source, a fluid that can carry metal, a pathway to focus it, a trap that makes it drop the metal, a seal to keep it there long enough, and preservation afterwards. Every link must hold, and every deposit is structurally controlled."},
 {"id": "L1-x-trap", "lecture": 1, "kind": "q", "front": "Hydrothermal fluids are usually undersaturated in metals. What fast changes make them drop their load?", "back": "The fluid cools, the pressure falls and it boils, it mixes with cooler groundwater, or it reacts with a rock (limestone is the classic) that neutralises its acidity. Each pass leaves only a little metal, so you need an enormous volume of fluid through the same small volume of rock."},
 {"id": "L1-x-hypo", "lecture": 1, "kind": "q", "front": "Hypogene versus hypothermal: what does each word describe?", "back": "Hypogene is fluid direction (rising). Hypothermal is depth and temperature (deep, hot). An epithermal deposit is still hypogene."},
 {"id": "L1-x-strata", "lecture": 1, "kind": "q", "front": "Stratiform, stratabound and discordant ore: what's the difference?", "back": "Stratiform ore forms as a layer within the sediment. Stratabound ore is confined to one unit but may have replaced it later. Discordant ore cuts across layering."},
 {"id": "L1-x-200c", "lecture": 1, "kind": "q", "front": "What rule of thumb lets chalcopyrite act as a thermometer?", "back": "Chalcopyrite generally needs more than about 200 °C, so a sample full of it probably isn't epithermal. A vein of galena, sphalerite and fine banded quartz points to the shallow, cooler end."},
 {"id": "L1-x-ladder", "lecture": 1, "kind": "q", "front": "Which resource categories can become which reserve categories?", "back": "Indicated can become probable. Measured can become proved, or only probable if some modifying factor is still uncertain. Inferred never converts directly."},
 {"id": "L2-x-three", "lecture": 2, "kind": "q", "front": "Weathering, oxidation and alteration: pin each one down in a line.", "back": "Weathering is physical and chemical breakdown of rock near the surface, needing air, water and often plants. Oxidation (for ore) is sulphides and carbonates turning into oxides and hydroxides when oxygenated water reaches them. Alteration is a change in a rock's minerals at low pressure because fluids moved through it, anywhere those fluids go."},
 {"id": "L2-x-kinds", "lecture": 2, "kind": "q", "front": "Name four kinds of alteration, from the obvious to the invisible.", "back": "Mineralogical (new minerals you can see, such as phyllic or propylitic). Mineral structural (same mineral, changed crystal structure, such as illite crystallinity). Geochemical or cryptic (only the chemistry changes, such as barium around VHMS). Isotopic (shifted isotope ratios, important around Carlin-type gold)."},
 {"id": "L3-x-families", "lecture": 3, "kind": "q", "front": "What are the three families of ore texture?", "back": "Breccias (broken rock: how it broke, moved and was cemented tells you what broke it). Ore classifications by abundance and layering (massive, semi-massive, disseminated, banded). Veins (cracks that opened and filled, recording a sequence of events)."},
 {"id": "L4-x-why", "lecture": 4, "kind": "q", "front": "Give three questions ore microscopy answers for a mine.", "back": "Which mineral hosts the metal (free gold is cheap to recover; refractory gold locked in pyrite or arsenopyrite is not). How big the grains are (that sets how finely you must grind). Whether there are dirty minerals (arsenic and tellurium phases attract smelter penalties)."},
 {"id": "L4-x-yellows", "lecture": 4, "kind": "q", "front": "Pyrite, chalcopyrite and gold are all yellow in reflected light. How do you tell them apart?", "back": "Pyrite is pale yellow, hard and takes a perfect polish. Chalcopyrite is a stronger yellow and soft. Gold is yellow-orange and so bright it still glows with the lamp turned right down, and it polishes poorly."},
 {"id": "L4-x-marcasite", "lecture": 4, "kind": "q", "front": "Pyrite or marcasite?", "back": "Both are FeS₂. Marcasite is more bronze-yellow and strongly anisotropic in blue and yellow-green. It also breaks down in warm, humid air."},
 {"id": "L4-x-galena-apy", "lecture": 4, "kind": "q", "front": "Galena or arsenopyrite? Both are white.", "back": "Galena is soft, isotropic and covered in triangular cleavage pits. Arsenopyrite is hard, anisotropic and forms sharp rhomb-shaped crystals."},
 {"id": "L5-x-jobs", "lecture": 5, "kind": "q", "front": "What four jobs do structures do for ore?", "back": "Make space (faults, fractures and dilational jogs open gaps). Block flow (gouge, impermeable beds and dykes seal, so fluid ponds and drops its load). Soften rock (deformation plus fluid makes weak chlorite and talc rock). Move ore (a later fault slices a deposit and shifts part of it)."},
 {"id": "L5-x-deform", "lecture": 5, "kind": "q", "front": "What are the three basic ways to deform a block of rock?", "back": "Pull it apart (extension, normal faults), push it together (compression, reverse and thrust faults, folds), or slide it sideways (strike-slip). Each makes different space and moves fluid differently, so each makes different ore geometries."},
 {"id": "L5-x-geometry", "lecture": 5, "kind": "q", "front": "Same limestone, same fault. How does the ore body differ between extension and compression?", "back": "In extension the fault opens a pathway, meteoric water flows down and mixes with basinal fluid, and you get one large lens on the fault. In compression the fold and fault act as an aquitard: fluid is squeezed up beneath it and replaces favourable beds, giving a series of smaller lenses."},
 {"id": "L5-x-dyke", "lecture": 5, "kind": "q", "front": "Why are so many gold mines called \"Golden Dyke\" when the dyke itself carries little gold?", "back": "The dyke intruded before the gold event and then acted as a barrier (an aquitard) to the gold-bearing fluid, which dumped its gold right against the dyke contact. A structure doesn't have to be permeable to control ore."}
);
